window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d01_prj90"]={"title": "3494-2-пос-изм3", "pages": 81, "pagesTxt": ["[стр. 1]\n", "[стр. 2]\n3494.2-ПОС 2 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПРОЕКТНАЯ ДОКУМЕНТАЦИЯ РАЗРАБОТАНА В СООТВЕТСТВИИ С ЗАДАНИЕМ \r\nНА ПРОЕКТИРОВАНИЕ, ДОКУМЕНТАМИ ОБ ИСПОЛЬЗОВАНИИ ЗЕМЕЛЬНОГО \r\nУЧАСТКА ДЛЯ СТРОИТЕЛЬСТВА, ТЕХНИЧЕСКИМИ РЕГЛАМЕНТАМИ И \r\nНОРМАТИВНОЙ ДОКУМЕНТАЦИЕЙ ПО БЕЗОПАСНОСТИ В ПРОМЫШЛЕННОСТИ\r\nГлавный инженер проекта Г.Н.Смирнов", "[стр. 3]\n3494.2-ПОС 3 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nСПИСОК ИСПОЛНИТЕЛЕЙ \r\nДолжность Подпись И.О. Фамилии Дата \r\nГлавный инженер проекта Г.Н.Смирнов \r\nСтроительный отдел \r\nНачальник отдела С.В.Васильев \r\nИнженер I категории А.В. Писарев", "[стр. 4]\n3494.2-ПОС 4 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nОГЛАВЛЕНИЕ \r\n1. ОБЩИЕ ДАННЫЕ ...................................................................................................................... 7\r\n2. ХАРАКТЕРИСТИКА РАЙОНА ПО МЕСТУ РАСПОЛОЖЕНИЯ ОБЪЕКТА КАПИТАЛЬНОГО \r\nСТРОИТЕЛЬСТВА И УСЛОВИЙ СТРОИТЕЛЬСТВА............................................................................ 10\r\n2.1 Общие сведения............................................................................................................... 10\r\n2.2 Топографические и геоморфологические условия площадки ....................................... 11\r\n2.3 Климатические условия .................................................................................................. 12\r\n2.4 Температура воздуха ....................................................................................................... 12\r\n2.5 Ветровой режим ............................................................................................................... 14\r\n2.6 Атмосферные явления..................................................................................................... 15\r\n2.7 Влажность воздуха и осадки............................................................................................ 15\r\n2.8 Геологические условия .................................................................................................... 16\r\n2.9 Сейсмические условия площадки строительства .......................................................... 16\r\n3. ОЦЕНКА РАЗВИТОСТИ ТРАНСПОРТНОЙ ИНФРАСТРУКТУРЫ............................................................ 17\r\n4. СОСТАВ ПРОЕКТИРУЕМЫХ СООРУЖЕНИЙ ПО ХВОСТОВОМУ ХОЗЯЙСТВУ И ОБОРОТНОГО \r\nВОДОСНАБЖЕНИЯ...................................................................................................................... 17\r\n4.1 Состав проектируемых сооружений ................................................................................ 17\r\n5. ОПИСАНИЕ ПРИНЯТЫХ ОБЪЁМНО-ПЛАНИРОВОЧНЫХ РЕШЕНИЙ ЗДАНИЙ И СООРУЖЕНИЙ............... 19\r\n5.1 Верховая ограждающая дамба........................................................................................ 19\r\n5.2 Низовая водоудерживающая дамба ............................................................................... 20\r\n5.3 Фильтрующая дамба........................................................................................................ 21\r\n5.4 Разделительная дамба.................................................................................................... 21\r\n5.5 Общие положения ............................................................................................................ 22\r\n5.6 Автодороги........................................................................................................................ 22\r\n5.7 Дамбы обвалования......................................................................................................... 22\r\n5.8 Намывная дамба .............................................................................................................. 23\r\n5.9 Здания и сооружения хвостового сооружения................................................................ 23\r\n6. СВЕДЕНИЯ О ВОЗМОЖНОСТИ ИСПОЛЬЗОВАНИЯ МЕСТНОЙ РАБОЧЕЙ СИЛЫ ПРИ ОСУЩЕСТВЛЕНИИ \r\nСТРОИТЕЛЬСТВА........................................................................................................................ 24\r\n7. ПЕРЕЧЕНЬ МЕРОПРИЯТИЙ ПО ПРИВЛЕЧЕНИЮ ДЛЯ ОСУЩЕСТВЛЕНИЯ СТРОИТЕЛЬСТВА \r\nКВАЛИФИЦИРОВАННЫХ СПЕЦИАЛИСТОВ, В ТОМ ЧИСЛЕ ДЛЯ ВЫПОЛНЕНИЯ РАБОТ ВАХТОВЫМ \r\nМЕТОДОМ.................................................................................................................................. 24\r\n8.ХАРАКТЕРИСТИКА ЗЕМЕЛЬНОГО УЧАСТКА, ПРЕДОСТАВЛЕННОГО ДЛЯ СТРОТЕЛЬСТВА,\r\nОБОСНОВАНИЕ НЕОБХОДИМОСТИ ИСПОЛЬЗОВАНИЯ ДЛЯ СТРОИТЕЛЬСТВА ЗЕМЕЛЬНЫХ УЧАСТКОВ \r\nВНЕ ЗЕМЕЛЬНОГО УЧАСТКА, ПРЕДОСТАВЛЕННОГО ДЛЯ СТРОИТЕЛЬСТВА ОБЪЕКТА........................ 24\r\n9. ОПИСАНИЕ ОСОБЕННОСТЕЙ ПРОВЕДЕНИЯ РАБОТ В УСЛОВИЯХ ДЕЙСТВУЮЩЕГО ПРЕДПРИЯТИЯ, В \r\nМЕСТАХ РАСПОЛОЖЕНИЯ ПОДЗЕМНЫХ КОММУНИКАЦИЙ, ЛИНИЙ ЭЛЕКТРОПЕРЕДАЧИ И СВЯЗИ ...... 25", "[стр. 5]\n3494.2-ПОС 5 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n10. ОБОСНОВАНИЕ ПРИНЯТОЙ ОРГАНИЗАЦИОННО-ТЕХНОЛОГИЧЕСКОЙ СХЕМЫ, ОПРЕДЕЛЯЮЩЕЙ \r\nПОСЛЕДОВАТЕЛЬНОСТЬ ВОЗВЕДЕНИЯ ЗДАНИЙ И СООРУЖЕНИЙ, ИНЖЕНЕРНЫХ И ТРАНСПОРТНЫХ \r\nКОММУНИКАЦИЙ, ОБЕСПЕЧИВАЮЩИЙ СОБЛЮДЕНИЕ УСТАНОВЛЕННЫХ В КАЛЕНДАРНОМ ПЛАНЕ \r\nСТРОТЕЛЬСТВА СРОКОВ ЗАВЕРШЕНИЯ СТРОИТЕЛЬСТВА.............................................................. 26\r\n10.1 Обоснование методов производства основных строительно-монтажных \r\nработ................................................................................................................................. 26\r\n10.2 Организационные вопросы............................................................................................ 29\r\n11. ПЕРЕЧЕНЬ ВИДОВ СТРОИТЕЛЬНЫХ И МОНТАЖНЫХ РАБОТ, ОТВЕТСТВЕННЫХ КОНСТРУКЦИЙ,\r\nУЧАСТКОВ СЕТЕЙ ИНЖЕНЕРНО-ТЕХНИЧЕСКОГО ОБЕСПЕЧЕНИЯ, ПОДЛЕЖАЩИХ \r\nОСВИДЕТЕЛЬСТВОВАНИЮ С СОСТАВЛЕНИЕМ СООТВЕТСВУЮЩИХ АКТОВ ПРИЕМКИ ПЕРЕД \r\nПРОИЗВОДСТВОМ ПОСЛЕДУЮЩИХ РАБОТ И УСТРОЙСТВОМ ПОСЛЕДУЮЩИХ КОНСТРУКЦИЙ........... 30\r\n12. ТЕХНОЛОГИЧЕСКАЯ ПОСЛЕДОВАТЕЛЬНОСТЬ РАБОТ ПРИ ВОЗВЕДЕНИИ ОБЪЕКТОВ \r\nКАПИТАЛЬНОГО СТРОИТЕЛЬСТВА ИЛИ ИХ ОТДЕЛЬНЫХ ЭЛЕМЕНТОВ .............................................. 33\r\n12.1 Технологическая последовательность работ............................................................... 33\r\n12.1.1 Земляные работы.............................................................................................. 34\r\n12.1.2 Устройство бетонных и железобетонных конструкций.................................... 35\r\n12.1.3 Монтаж строительных конструкций................................................................... 37\r\n12.1.4 Монтаж технологического оборудования......................................................... 37\r\n12.2 Технологическая последовательность возведения насосных..................................... 38\r\n12.3 Производство работ в зимних условиях........................................................................ 39\r\n12.3.1 Земляные работы............................................................................................... 39\r\n12.3.2 Бетонные и железобетонные работы ............................................................... 39\r\n12.3.3 Монтаж строительных конструкций................................................................... 40\r\n13. ОБОСНОВАНИЕ ПОТРЕБНОСТИ СТРОИТЕЛЬСТВА В КАДРАХ, ОСНОВНЫХ СТРОИТЕЛЬНЫХ \r\nМАШИНАХ, МЕХАНИЗМОВ, ТРАНСПОРТНЫХ СРЕДСТВАХ, В ТОПЛИВЕ И ГОРЮЧЕ-СМАЗОЧНЫХ \r\nМАТЕРИАЛАХ, А ТАКЖЕ В ЭЛЕКТРИЧЕСКОЙ ЭНЕРГИИ, ВОДЕ, ВРЕМЕННЫХ ЗДАНИЯХ И \r\nСООРУЖЕНИЯХ.......................................................................................................................... 41\r\n13.1 Потребность рабочих кадров при строительстве......................................................... 41\r\n13.2 Обоснование потребности строительства в основных строительных \r\nмашинах, механизмов, транспортных средствах........................................................... 42\r\n13.3 Обоснование потребности строительства в топливе и горюче-смазочных \r\nматериалах, а также в электрической энергии, в сжатом воздухе, воде...................... 43\r\n13.3.1 Обоснование потребности в топливе, ГСМ ...................................................... 43\r\n13.3.2 Расчет искусственного освещения строительной площадки........................... 44\r\n13.3.3 Обоснование потребности в электроэнергии ................................................... 45\r\n13.3.4 Обоснование потребности в паре ..................................................................... 45\r\n13.3.5 Обоснование потребности в сжатом воздухе................................................... 46\r\n13.3.5 Обоснование потребности в воде ..................................................................... 46\r\n13.4 Обоснование потребности строительства во временных зданиях и \r\nсооружениях..................................................................................................................... 47\r\n14. ОБОСНОВАНИЕ РАЗМЕРОВ И ОСНАЩЕНИЯ ПЛОЩАДОК ДЛЯ СКЛАДИРОВАНИЯ МАТЕРИАЛОВ,\r\nКОНСТРУКЦИЙ, ОБОРУДОВАНИЯ, УКРУПНЕННЫХ МОДУЛЕЙ И СТЕНДОВ ДЛЯ ИХ СБОРКИ. РЕШЕНИЯ", "[стр. 6]\n3494.2-ПОС 6 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПО ПЕРЕМЕЩЕНИЮ ТЯЖЕЛОВЕСНОГО НЕГАБАРИТНОГО ОБОРУДОВАНИЯ, УКРУПНЕННЫХ \r\nМОДУЛЕЙ И СТРОИТЕЛЬНЫХ КОНСТРУКЦИЙ ................................................................................ 50\r\n15. ПРЕДЛОЖЕНИЯ ПО ОБЕСПЕЧЕНИЮ КОНТРОЛЯ КАЧЕСТВА СТРОИТЕЛЬНЫХ И МОНТИРУЕМЫХ \r\nОБОРУДОВАНИЯ, КОНСТРУКЦИЙ И МАТЕРИАЛОВ ......................................................................... 51\r\n16. ПРЕДЛОЖЕНИЯ ПО ОРГАНИЗАЦИИ СЛУЖБЫ ГЕОДЕЗИЧЕСКОГО И ЛАБОРАТОНОГО КОНТРОЛЯ....... 54\r\n17. ПЕРЕЧЕНЬ ТРЕБОВАНИЙ, КОТОРЫЕ ДОЛЖНЫ БЫТЬ УЧТЕНЫ В РАБОЧЕЙ СТАДИИ ДОКУМЕНТАЦИИ 55\r\n18. ОБОСНОВАНИЕ ПОТРЕБНОСТИ В ЖИЛЬЕ И СОЦИАЛЬНО-БЫТОВОМ ОБСЛУЖИВАНИИ ПЕРСОНАЛА,\r\nУЧАСТВУЮЩЕГО В СТРОИТЕЛЬСТВЕ ........................................................................................... 56\r\n19. ПЕРЕЧЕНЬ МЕРОПРИЯТИЙ И ПРОЕКТНЫХ РЕШЕНИЙ ПО ОПРЕДЕЛЕНИЮ ТЕХНИЧЕСКИХ СРЕДСТВ \r\nИ МЕТОДОВ РАБОТЫ, ОБЕСПЕЧИВАЮЩИХ ВЫПОЛНЕНИЕ НОРМАТИВНЫХ ТРЕБОВАНИЙ ОХРАНЫ \r\nТРУДА ....................................................................................................................................... 56\r\n19.1 Техника безопасности и противопожарные мероприятия в период \r\nорганизации строительства............................................................................................. 69\r\n20. ОПИСАНИЕ ПРОЕКТНЫХ РЕШЕНИЙ И МЕРОПРИЯТИЙ ПО ОХРАНЕ ОКРУЖАЮЩЕЙ СРЕДЫ В \r\nПЕРИОД СТРОИТЕЛЬСТВА........................................................................................................... 71\r\n21. ОБОСНОВАНИЕ ПРИНЯТОЙ ПРОДОЛЖИТЕЛЬНОСТИ СТРОИТЕЛЬСТВА ОБЪЕКТА КАПИТАЛЬНОГО \r\nСТРОИТЕЛЬСТВА И ЕГО ОТДЕЛЬНЫХ ЭТАПОВ .............................................................................. 74\r\n22. СТРОЙГЕНПЛАН И ТРАНСПОРТ .................................................................................................. 74\r\n23.ТЕХНИКО-ЭКОНОМИЧЕСКИЕ ПОКАЗАТЕЛИ................................................................................... 75\r\n24. ПЕРЕЧЕНЬ МЕРОПРИЯТИЙ ПО ОРГАНИЗАЦИИ МОНИТОРИНГА ЗА СОСТОЯНИЕМ ЗДАНИЙ И \r\nСООРУЖЕНИЙ, РАСПОЛОЖЕННЫХ В НЕПОСРЕДСТВЕННОЙ БЛИЗОСТИ ОТ СТРОЯЩЕГОСЯ \r\nОБЪЕКТА, ЗЕМЛЯНЫЕ, СТРОИТЕЛЬНЫЕ, МОНТАЖНЫЕ И ИНЫЕ РАБОТЫ НА КОТОРЫЕ МОГУТ \r\nПОВЛИЯТЬ НА ТЕХНИЧЕСКОЕ СОСТОЯНИЕ И НАДЕЖНОСТЬ ТАКИХ ЗДАНИЙ И СООРУЖЕНИЙ........... 76\r\nПРИЛОЖЕНИЯ................................................................................................................................ 77\r\nПриложение А ВЕДОМОСТЬ ПОТРЕБНОСТИ В СТРОИТЕЛЬНЫХ \r\nМАТЕРИАЛАХ, КОНСТРУКЦИЯХ ................................................................................... 78\r\nЧЕРТЕЖИ....................................................................................................................................... 79\r\nПеречень чертежей................................................................................................................ 80", "[стр. 7]\n3494.2-ПОС 7 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n1. ОБЩИЕ ДАННЫЕ \r\nНастоящая проектная документация выполнена на основании техниче￾ского задания ЗФ ОАО \"ГМК \"Норильский никель\" на выполнение проектной \r\nдокументации \"Реконструкции и технического перевооружения ТОФ с увели￾чением мощности до 16 млн.т по сумме руд\" от 24.12.2010 г., утверждённого \r\nПервым заместителем директора ЗФ ОАО \"ГМК \"Норильский никель\". \r\nПроектная документация выполнена в соответствии с \"Техническими \r\nусловиями на корректировку проектно-сметной документации по объекту \r\n\"Реконструкция и техническое перевооружение ТОФ с увеличением мощно￾сти до 16 млн. т по сумме руд (шифр ТОФ-РФ) от 24.12.2010 г., утверждён￾ного Первым заместителем директора ЗФ ОАО \"ГМК \"Норильский никель\". \r\nТехническое задание и Технические условия приведены в томе 1.1 \r\n\"Обогатительная фабрика. Состав проектной документации. Раздел 1\". \r\nЗАО \"Механобр инжиниринг\" имеет \"Свидетельство о допуске к рабо￾там по подготовке проектной документации, которые оказывают влияние на \r\nбезопасность объектов капитального строительства\". Регистрационный но￾мер П-044-023.2 от 26.05.2011 г. \r\nВ данной работе рассмотрен вопрос организациистроительства нового \r\nхвостохранилища для складирования отвальных хвостов ТОФ ввиду недос￾таточных мощностей хвостохранилища \"Лебяжье\". \r\nДля складирования хвостов ТОФ предусматривается строительство но￾вого хвостохранилища, расположенного на расстоянии около 6 км от промп￾лощадки фабрики в междуречье рек Хараелах − Томулах площадью 10,95 \r\nкм2\r\n, включающую территории недействующего отстойника Хараелах и не￾действующего карьера песчано-гравийного грунта \"Дальний\". \r\nВ проекте приняты технические решения по строительству нового хво￾стохранилища, разработанные в \"ТЭР вариантов строительства нового хво￾стохранилища\", с учётом замечаний и предложений Заказчика. \r\nВ проекте рассмотрены следующие технологические системы: \r\n1. Новое хвостовое хозяйство для гидротранспорта, складирования, \r\nотстоя хвостовой пульпы в хвостохранилище и возврата осветлён￾ной жидкой фазы пульпы в пруд-накопитель ТОФ. \r\n2. Существующая высоконапорная система гидротранспорта для \r\nтранспортирования концентратных пульп на металлургические за-", "[стр. 8]\n3494.2-ПОС 8 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nводы и возврата сливов сгустителей концентратных пульп с метал￾лургических заводов в пруд-накопитель ТОФ. \r\n3. Частично реконструируемая существующая система внешнего обо￾ротного водоснабжения ТОФ для подачи осветлённой воды из пру￾да-накопителя в баки оборотной воды. \r\nВ состав проектируемых сооружений хвостового хозяйства входят: \r\n1. Сооружения системы складирования хвостов. Сооружения предна￾значены для складирования хвостов, отстоя хвостовой пульпы и ос￾ветления в отстойном пруде хвостохранилища оборотной воды. \r\n2. Сооружения системы гидротранспорта хвостов. Сооружения пред￾назначены для подачи хвостов из главного корпуса ТОФ на хвосто￾хранилище. \r\n3. Сооружения системы оборотного водоснабжения. Сооружения пред￾назначены для подачи оборотной воды из отстойного пруда хвосто￾хранилища в пруд-накопитель ТОФ. \r\n4. Сооружения системы охраны окружающей среды предназначены \r\nдля предотвращения загрязнения и контроля состояния окружаю￾щей природной среды. \r\nСхема сооружений представлена на рис. 1.", "[стр. 9]\n3494.2-ПОС 9 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc", "[стр. 10]\n3494.2-ПОС 10 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n2. ХАРАКТЕРИСТИКА РАЙОНА ПО МЕСТУ РАСПОЛОЖЕНИЯ \r\nОБЪЕКТА КАПИТАЛЬНОГО СТРОИТЕЛЬСТВА И УСЛОВИЙ \r\nСТРОИТЕЛЬСТВА \r\n2.1 ОБЩИЕ СВЕДЕНИЯ\r\nПлощадка хвостохранилища расположена в Норильском промышлен￾ном районе, на территории района Талнах в 6-7 км от г.Талнах. \r\nПо своему физико-географическому положению плщадка проектирова￾ния расположена в пределах западно-бугристой Норильско-Рыбнинской до￾лины, входящей в состав Среднесибирского плоскогорья. \r\nВ геоморфологическом отношении площадка приурочена к озёрно￾бугристой долине реки Норильская и расположена в пределах междуречья \r\nрек Хараелах и Томулах. \r\nВ восточной части площадки располагается недействующий отстойник \r\n(пруд-окислитель), построенный по проекту института \"Механобр\" на месте \r\nозера Хараелах. В юго-восточной части площадки находится карьер \"Даль￾ний\" песчано-гравийной смеси. Карьер с 1988 г. не эксплуатируется. В ре￾зультате разработок естественный рельеф сильно нарушен, в центральной \r\nчасти грунт выбран, а по контуру мощность насыпного грунта достигает 18 м. \r\nВ северной и западной части рельеф площадки не нарушен и пред￾ставлен растительностью, характерной для лесотундры. \r\nАбсолютные отметки поверхности площадки колеблются от 32 до 75 \r\nметров. Общий уклон поверхности рельефа наблюдается в северо￾западном направлении в сторону оз.Пясино. \r\nГидрографическая сеть на площадке представлена озёрами и ручьями, \r\nбольшая часть которых находится в северной части. В 3500 метрах к запа￾ду находится р.Норильская с многочисленными протоками. В 300 метрах к \r\nюгу от площадки протекает р.Хараелах, в 300-500 метрах к северу протекает \r\nр.Томулах. \r\nГеологический разрез площадки представлен отложениями четвертич￾ной, девонской системы и породами магматического комплекса позднеперм￾ской и триасовой систем нерасчленённых. \r\nРайон строительства хвостохранилища относится к IБ строительно￾климатической зоне, располагается в зоне тундры, характеризуется распро￾странением вечномёрзлых грунтов.", "[стр. 11]\n3494.2-ПОС 11 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nКлимат района субарктический, характеризуется отрицательной сред￾негодовой температурой воздуха, продолжительной зимой с сильными мо￾розами и метелями, холодным, часто дождливым летом.\r\nСреднегодовая за многолетний период температура воздуха составля￾ет минус 10,1оС. \r\nПереходные сезоны (весна и осень) очень короткие. \r\nХарактерным для района является частая и резкая смена погоды, не￾определённость общеустановленных сезонов. \r\nСреднегодовое количество осадков − 561 мм. \r\nНаправление ветров в зимний период южное и юго-восточное, летом −\r\nсеверное, северо-западное. \r\n2.2 ТОПОГРАФИЧЕСКИЕ И ГЕОМОРФОЛОГИЧЕСКИЕ УСЛОВИЯ ПЛОЩАДКИ\r\nВ административном отношении район строительства сооружений хво￾стового хозяйства находится в Норильском промышленном районе на тер￾ритории Таймырского (Долгано-ненецкого) автономного округа Красноярско￾го края. \r\nПо своему физико-географическому положению территория строитель￾ства расположена в пределах Западно-бугристой Норильско-Рыбинской до￾лины, входящей в состав Средне-Сибирского плоскогорья. \r\nПлощадка строительства хвостохранилища расположена в пределах \r\nмеждуречья рек Томулах и Хараелах. \r\nВ восточной части площадки располагается отстойник (пруд￾окислитель), построенный по проекту института \"Механобр\" на месте озера \r\nХараелах. В юго-восточной части площадки находится карьер \"Дальний\" \r\nпесчано-гравийной смеси. Карьер с 1988 г. не эксплуатируется. В результа￾те разработок естественный рельеф сильно нарушен, в центральной части \r\nгрунт выбран, по контуру мощность насыпного грунта достигает 18 м. \r\nВ северной и западной части рельеф площадки не нарушен, флора \r\nпредставлена растительностью, характерной для лесотундры. \r\nАбсолютные отметки поверхности площадки колеблются от 40 до 70 \r\nметров. Общий уклон поверхности рельефа наблюдается в северо￾западном направлении в сторону оз.Пясино. \r\nГидрографическая сеть на площадке представлена озёрами и ручьями, \r\nбольшая часть которых находится в северной части. В 3,5 км к западу находится \r\nр.Норильская с многочисленными протоками. В 300 метрах к югу от площадки \r\nпротекает р.Хараелах, в 300-500 метрах к северу протекает р.Томулах.", "[стр. 12]\n3494.2-ПОС 12 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nСток с южной и юго-западной части площадки поступает в р.Хараелах, \r\nс северной и северо-западной части − в р.Томулах. Сток с водосбора от￾стойника Хараелах поступает в р.Томулах. \r\nВ тектоническом отношении район расположения хвостохранилища \r\nсложный, обусловленный широким развитием тектонических трещин. Глав￾ным структурным элементом является зона Норильско-Хараелахского раз￾лома. Зона разлома представляет собой грабенно-подобную структуру. \r\n2.3 КЛИМАТИЧЕСКИЕ УСЛОВИЯ \r\nРайон строительства расположен в субарктическом климатическом поя￾се. Климат формируется под влиянием тёплого Атлантического и холодного \r\nАрктического бассейнов. В зимний период сюда проникают преимуществен￾но холодные арктические воздушные массы. \r\nКлимат района строительства характеризуется отрицательной средне￾годовой температурой воздуха, продолжительной зимой с сильными моро￾зами и метелями, коротким дождливым, холодным летом, наличием частых \r\nи резких смен погоды. \r\nРазграничить сезоны года (весну, лето, осень) невозможно, за исклю￾чением зимы, которая продолжается здесь восемь месяцев (с Х по V). \r\nТемпературный режим воздуха характеризуется: низкими температура￾ми, большой продолжительностью холодного периода, большим контрастом \r\nзимних и летних температур. \r\nСогласно СНиП 23-01-99 \"Строительная климатология\" район работ от￾носится к климатическому району − 1, климатическому подрайону Б. \r\nСогласно СНиП 23-01-99 зона влажности 2 − нормальная. \r\nСогласно СНиП 23-01-99 район работ относится к 3 северной строи￾тельно-климатической зоне − наиболее суровые условия. \r\nСогласно ГОСТ 16350-80 макроклиматический район работ − холодный, \r\nклиматический район − очень холодный (II). \r\n2.4 ТЕМПЕРАТУРА ВОЗДУХА\r\nТемпературный режим района строительства носит континентальный ха￾рактер. \r\nПериод с отрицательными средними месячными температурами возду￾ха продолжается около 7 месяцев − с октября по май. Средняя температура \r\nэтого периода составляет минус 13оС.", "[стр. 13]\n3494.2-ПОС 13 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nСамым холодным месяцем является январь, средняя температура это￾го месяца − -27 − -28оС. \r\nПереход температуры воздуха через 10оС, характеризующий начало \r\nлетнего сезона, происходит 19 июня. Продолжительность летнего сезона \r\nсоставляет 60-70 дней. Наиболее высокие температуры приурочены к ию￾лю, средняя температура которого равна 14,2оС. \r\nТемпературные характеристики приведены в таблицах 1,2. \r\nТаблица 1 \r\nТемпературные характеристики, оС \r\nХарактеристика Величина Метеостанция \r\n1. Среднегодовая температура воздуха -9,5 Норильск \r\n2. Абсолютная температура воздуха \r\nминимальная -56,1 ―\"― \r\nмаксимальная 32,2 ―\"― \r\n3. Температура воздуха наиболее холодной \r\nпятидневки обеспеченностью \r\n \r\n0,98 -48,0 ―\"― \r\n0,92 -45,8 ―\"― \r\n4. Амплитуда колебания среднемесячных \r\nтемператур \r\n41,8 ―\"― \r\n5. Абсолютная амплитуда 88,3 ―\"― \r\nТаблица 2 \r\nСредняя месячная и годовая температура воздуха, оС \r\nметеостанция Норильск \r\nI II III IV V VI VII VIII IX X XI XII год \r\n-27,6 -27,0 -21,3 -14,3 -5,0 6,5 14,2 11,3 3,9 -8,6 -21,0 -25,2 -9,5 \r\nСредняя продолжительность безморозного периода составляет 115-\r\n120 дней. \r\nПервые устойчивые морозы наступают в конце сентября, заканчивают￾ся в начале июня. \r\nПромерзание грунтов в этом районе начинается в конце октября − на￾чале ноября, полное оттаивание происходит в середине мая. Наибольшая", "[стр. 14]\n3494.2-ПОС 14 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nглубина промерзания обычно наблюдается в феврале-марте и достигает в \r\nестественных условиях 1,2-2 м. \r\nНормативная глубина сезонного промерзания глинистых и суглинистых \r\nгрунтов составляет 3,0 м, супесей и песков − 3,1 м, торфов − 0,7 м. \r\n2.5 ВЕТРОВОЙ РЕЖИМ\r\nВ течение всего года в районе изысканий преобладают восточные и \r\nюго-восточные ветры, число случаев с ветром этих направлений составляет\r\nв среднем за год 43%. Среднегодовая скорость ветра составляет 5,4 м/с. \r\nНаименьшее среднемесячное значение скорости ветра (4,1 м/с) наблюдает￾ся в августе, наибольшее (6,0 − 6,1 м/с) − с декабря по апрель. Максималь￾ная скорость ветра достигает 40 м/с. \r\nСреднее число дней со скоростью более 8 м/с составляет 46, со скоро￾стью более 15 м/с − 14. \r\nПри антициклоническом характере погоды над рассматриваемой терри￾торией в зимние месяцы наблюдается большая повторяемость штилей. \r\nВ таблицах 3, 4 представлены ветровые характеристики. \r\nТаблица 3 \r\nВетровые характеристики \r\nХарактеристика Величина Метеостанция \r\n1. Средняя годовая скорость ветра, м/с 5,4 Норильск\r\n2. Преобладающее направление ветра В, ЮВ ―\"― \r\n3. Наибольшая скорость ветра, м/с, \r\nвозможная один раз за 1 год 10 ―\"―\r\n10 лет 28 ―\"― \r\n20 лет 30 ―\"― \r\nТаблица 4 \r\nСредняя месячная и годовая скорость ветра (м/с) \r\nметеостанция Норильск \r\nI II III IV V VI VII VIII IX X XI XII год \r\n6,0 5,4 6,0 6,1 5,8 5,0 4,2 4,1 4,5 5,7 5,5 6,1 5,4", "[стр. 15]\n3494.2-ПОС 15 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nНормативное значение ветрового давления для района строительства, \r\nпринадлежащего IV ветровому району, составляет 48 кгс/м2\r\n. \r\n2.6 АТМОСФЕРНЫЕ ЯВЛЕНИЯ\r\nЗа год в рассматриваемом районе наблюдаются в среднем 40-45 дней \r\nс туманом, причём наибольшее их количество (9) приходится на январь. \r\nНаибольшее за год число дней с туманом − 83. Средняя продолжительность \r\nтумана зимой 5,3 часа, летом − 3,2 часа. \r\nСреднее за год число дней с метелью составляет 66, наибольшее их \r\nколичество (11) приходится на декабрь − январь. Наибольшее число дней с \r\nметелью − 93. Средняя продолжительность метели − 9,2 часа. \r\nСреднее за год число дней с грозой − 5, наибольшее − 14. Наиболее часто \r\nгрозы отмечаются в июле. Среднегодовая продолжительность гроз составляет \r\n5,7 часов. . Среднегодовая продолжительность грозы равна 1,7 часа. \r\nСреднее за год число дней с градом составляет 0,4, наибольшее − 2. \r\nРайон строительства находится в пределах III гололёдной зоны азиат￾ской части России. Толщина стенки гололёда (в мм) на элементах кругового \r\nсечения диаметром 10 мм, превышаемая раз в 5 лет, равна 10 мм. \r\n2.7 ВЛАЖНОСТЬ ВОЗДУХА И ОСАДКИ\r\nВыпавшие в течение года атмосферные осадки по сезонам распреде￾ляются относительно равномерно. Так, за июнь-сентябрь, в результате раз￾вития циклонической деятельности, выпадает около 45% от общего количе￾ства осадков (213 мм). Сумма осадков за холодный период равна 266 мм. \r\nМаксимум их приходится на сентябрь, минимум − на февраль-апрель. \r\nСредняя месячная относительная влажность воздуха наиболее холод￾ного месяца − января составляет 77%, средняя месячная относительная \r\nвлажность июля − 68%. \r\nОбщее количество твёрдых осадков, выпадающих за холодный период, \r\nсоставляет около 55% годовой суммы. \r\nСредняя дата образования устойчивого снежного покрова − 30 сентяб￾ря, средняя дата разрушения − 26 мая. Среднее число дней с устойчивым \r\nснежным покровом составляет 244 дня. \r\nНаибольшая за зиму высота снежного покрова на открытом участке \r\nдостигает 80-90 см. Расчётная толщина снежного покрова вероятностью \r\nпревышения 5% составляет 81 см.", "[стр. 16]\n3494.2-ПОС 16 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nЗапас воды в снежном покрове достигает наибольшего значения в ап￾реле и составляет в этот период 110-120 мм, максимальный из наблюден￾ных составил − 200 мм. \r\n2.8 ГЕОЛОГИЧЕСКИЕ УСЛОВИЯ\r\nВ инженерно-геологическом строении площадки строительства соору￾жений хвостового хозяйства участвуют техногенные, биогенные, аллюви￾альные, элювиальные отложения верхнечетвертичного возраста, скальные \r\nгрунты девонского и триасового возраста. \r\nПо результатам выполненных инженерно-геологических изысканий тол￾ща грунтов оснований на площадке изысканий до разведанной глубины 33,0 \r\nм является неоднородной, в её пределах выделены 31 инженерно￾геологических элементов. \r\nВ основании площадки изысканий преимущественно распространены \r\nскальные и крупнообломочные грунты, что позволяет принимать II принцип \r\nиспользования вечномёрзлых грунтов в качестве основания сооружений. \r\nНормативная глубина сезонного промерзания глинистых и суглинистых \r\nгрунтов составляет 3,0 м. \r\nИнженерно-геологические условия (согласно приложения Б СП 11-105-\r\n97, часть 1) относятся к средней категории сложности. \r\nГрунты, слагающие площадку изысканий, согласно табл.1 \r\nСП 14.13330.2011 \"Строительство в сейсмических районах\", относятся к I и II \r\nкатегории по сейсмическим свойствам. \r\nНеблагоприятные процессы и явления и специфические грунты\r\nК неблагоприятным процессам, распространённым в пределах площад￾ки строительства, можно отнести развитие болот и озёр, динамику рек, что \r\nможет привести к таянию грунтов, морозному пучению, потери сплошного \r\nзалегания грунтов. \r\nНа площадке изысканий развиты специфические грунты, к которым от￾носятся техногенные грунты, сильнопучинистые грунты. Сильнопучинистые \r\nгрунты представлены глинами мягкопластичной консистенции, суглинками \r\nмягкопластичной консистенции. \r\n2.9 СЕЙСМИЧЕСКИЕ УСЛОВИЯ ПЛОЩАДКИ СТРОИТЕЛЬСТВА\r\nИнтенсивность сейсмического воздействия для районов строительства \r\nпринята на основе комплекта карт общего сейсмического районирования", "[стр. 17]\n3494.2-ПОС 17 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nтерритории Российской Федерации − ОСР-97, т.к. изданной карты сейсми￾ческого микрорайонирования нет. \r\nСогласно СП 14.13330.2011 и карты общего сейсмического райониро￾вания территории Российской Федерации (ОСР-97) расчётная сейсмическая \r\nинтенсивность в баллах шкалы MSK-64 для средних грунтовых условий в \r\nпределах района составляет: \r\n— 5 баллов − соответствует 10% вероятности; \r\n— 5 баллов − соответствует 5% и 1% вероятности. \r\n3. ОЦЕНКА РАЗВИТОСТИ ТРАНСПОРТНОЙ ИНФРАСТРУКТУРЫ \r\nСеть железных и автомобильных дорого развита удовлетворительно и \r\nобеспечивает своевременную подвозку материалов, конструкций, оборудо￾вания и полуфабрикатов на строительную площадку. \r\n4. СОСТАВ ПРОЕКТИРУЕМЫХ СООРУЖЕНИЙ ПО ХВОСТОВОМУ \r\nХОЗЯЙСТВУ И ОБОРОТНОГО ВОДОСНАБЖЕНИЯ \r\n4.1 СОСТАВ ПРОЕКТИРУЕМЫХ СООРУЖЕНИЙ\r\nСистемы и сооружения проектируемого хвостохранилища приведены в \r\nтаблице 5. \r\nТаблица 5 \r\n№№ Наименование \r\nсистемы \r\nНаименование сооружений \r\nПрименение и функции \r\nв проектируемом \r\nкомплексе ГТС \r\nВерховая ограждающая дамба \r\nпервой очереди строительства \r\nхвостохранилища \r\nВерховая ограждающая дамба \r\nвторой очереди строительства \r\nхвостохранилища \r\nНизовая водоудерживающая \r\nограждающая дамба \r\nРазделительная дамба \r\nОрганизация ёмкости для \r\nскладирования \r\nхвостов \r\nФильтрующая дамба \r\n1 Система \r\nскладирования \r\nхвостов \r\nОтстойный пруд \r\nхвостохранилища \r\nДля осветления оборот￾ной воды хвостохранили￾ща", "[стр. 18]\n3494.2-ПОС 18 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nОкончание таблицы 5 \r\n№№ Наименование \r\nсистемы \r\nНаименование сооружений \r\nПрименение и функции \r\nв проектируемом \r\nкомплексе ГТС \r\n Распределительные \r\nпульповоды, проложенные по \r\nгребню ограждающей \r\nверховой дамбы \r\nПроизводство намывных \r\nработ по складированию \r\nхвостов \r\nПульпонасосная станция (ПНС￾1А) в главном корпусе ТОФ \r\nМагистральные пульповоды от \r\nПНС-1А (ТОФ) до хвостохрани￾лища \r\n2 Система \r\nгидротранспорта \r\nхвостов \r\nУзел переключения \r\nтрубопроводов \r\nПодача хвостов на ограж￾дающую дамбу хвосто￾хранилища в распредели￾тельные пульповоды \r\nПлавучие насосные \r\nустановки \r\nНасосная станция оборотной \r\nводы \r\nВодоводы от плавучих насос￾ных установок до насосной \r\nстанции оборотной воды \r\n3 Система \r\nоборотного \r\nводоснабжения \r\nМагистральные водоводы от \r\nнасосной станции оборотной \r\nводы до пруда-накопителя ТОФ \r\nПодача осветлённой обо￾ротной воды на промпло￾щадку ТОФ \r\n4 Система КИА Установка в контрольных ство￾рах на ограждающей дамбе: \r\nпьезометров; \r\nреперов; \r\nтемпературных скважин; \r\nнаблюдательных скважин в \r\nнижнем бьефе ограждающих \r\nдамб. \r\nУстройство геодезической сети \r\nпо контуру хвостохранилища. \r\nКонтроль и наблюдение \r\nза состоянием ограждаю￾щей дамбы проектируемо￾го хвостохранилища и \r\nфизико-химического со￾става грунтовых вод ниж￾него бьефа ограждающей \r\nдамбы \r\nСуммарная площадь территории, занимаемой комплексом сооружений, \r\nсоставляет 11,865 км2\r\n. Граница земельного отвода под проектируемые со￾оружения хвостового хозяйства и оборотного водоснабжения утверждена \r\nАдминистрацией города Норильск Красноярского края в Постановлении Ад￾министрации города Норильска \"Об утверждении границ земельного участка \r\nв аренду\", №2608 от 13.12.2006 г. и №2702 от 23.07.2010 г.", "[стр. 19]\n3494.2-ПОС 19 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n5. ОПИСАНИЕ ПРИНЯТЫХ ОБЪЁМНО-ПЛАНИРОВОЧНЫХ \r\nРЕШЕНИЙ ЗДАНИЙ И СООРУЖЕНИЙ \r\nВ комплекс сооружений первой очереди строительства хвостохранили￾ща входит: \r\n1. Верховая дамба (южный и восточный участки). \r\n2. Разделительная дамба. \r\n3. Низовая дамба. \r\n4. Фильтрующая дамба. \r\nВо вторую очередь строительства входят северо-восточный и северный \r\nучастки верховой ограждающей дамбы. \r\nС верховой ограждающей дамбы, как первой, так и второй очереди строи￾тельства производится намыв хвостохранилища. Наращивание дамбы до ко￾нечной отметки заполнения хвостохранилища производится намывным спосо￾бом с устройством дамб обвалования из привозного грунта на намытые хвосты \r\nпляжа. Вдоль южного участка верховой дамбы проложены водоводы оборот￾ной воды от НОВ до узла переключения пульповодов и водоводов. \r\nРазделительная дамба предусмотрена для ограничения площади хво￾стохранилища на второй пусковой комплекс ТОФ. С разделительной дамбы \r\nпроизводится намыв по северному борту хвостохранилища первой очереди \r\nстроительства. \r\nНизовая ограждающая дамба является водоудерживающим гидротех￾ническим сооружением для отстойного пруда хвостохранилища, работаю￾щим при переменной величине гидростатического давления. Максимальный \r\nнапор на дамбу составляет 10 м. \r\nФильтрующая дамба предназначена для предотвращения попадания \r\nшламов при намыве хвостов с верховой дамбы в отстойный пруд хвосто￾хранилища. Створ дамбы расположен параллельно створу низовой водо￾удерживающей дамбы на расстоянии 450 м вглубь хвостохранилища. \r\n5.1 ВЕРХОВАЯ ОГРАЖДАЮЩАЯ ДАМБА \r\nВерховая дамба однородная земляная дамба. Протяжённость дамбы \r\n9307,5 м, в том числе 4330 м протяжённость дамбы первой очереди строи￾тельства хвостохранилища и 4977,5 м протяжённость дамбы второй очере￾ди строительства хвостохранилища. Первоначальная максимальная отмет-", "[стр. 20]\n3494.2-ПОС 20 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nка гребня дамбы составляет 72,0 м и с учётом понижения отметок рельефа \r\nместности снижается до 52 м. Наращивание дамбы до проектных отметок \r\nпроизводится намывным способом с устройством дамб обвалования. \r\nВерховая ограждающая дамба отсыпается из грунтов отвала вскрыш￾ных пород карьера \"Дальний\". Дамба отсыпается слоями толщиной 0,3 м с \r\nпослойным уплотнением до γск. = 1,65 т/м3\r\n. Крепление гребня и откосов пре￾дусмотрено гравийно-галечниковым грунтом толщиной слоя 1,0 м. \r\nОсновные параметры верховой дамбы: \r\n— отметка гребня − 72-52 м; \r\nширина по гребню − 15,0 м; \r\n— заложение верхового и низового откосов − 1:2; \r\n— максимальная высота в районе \r\nотработки карьера на длине 27 м − 25 м; \r\n— высота дамбы на длине 9280,5 м − 4-18 м. \r\nШирина дамбы по гребню 15 м принята из условия отсыпки дамбы боль￾шегрузным автотранспортом, прокладки распределительного пульповода, ус￾тановки столбов освещения, установки контрольно-измерительной аппаратуры \r\n(КИА) и проезжей части автодороги для их монтажа и обслуживания. \r\nПо длине дамбы через 2 км предусмотрены съезды в нижний бьеф дам￾бы. \r\n5.2 НИЗОВАЯ ВОДОУДЕРЖИВАЮЩАЯ ДАМБА\r\nКонструкция низовой дамбы разработана комбинированной с учётом \r\nгеологических и мерзлотных условий основания дамбы. В основании дамбы \r\nпредусматривается грунтовая подушка из гравийно-галечникового грунта \r\nhсл. − 2,5 м, допускающая развитие осадок, деформаций, просадок \r\nоснования. Дамба отсыпается из гравийно-галечникового грунта с \r\nустройством полимерного экрана (из геомембраны ПЭВП, текстурированной \r\nс двух сторон, \"Solmax\" 440Т), переходящего в противофильтрационный \r\nэлемент площади отстойного пруда. Подстилающий и защитный слои \r\nэкрана отсыпаются из песчаного грунта. \r\nПредусматривается пригрузка низового откоса скальным грунтом и при￾грузка верхового откоса по защитному слою из песка гравийно￾галечниковым грунтом. Толщина слоёв пригруза − 1,0 м. По гребню дамбы \r\nпредусмотрен выравнивающий слой из щебня (hсл. − 0,2 м).", "[стр. 21]\n3494.2-ПОС 21 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПараметры низовой дамбы: \r\n— протяжённость − 3194,57 м; \r\n— отметка гребня − 47,0 м; \r\n— ширина по гребню − 24,5 м; \r\n— заложение откосов \r\nверхового − 1:2,5; \r\nнизового − 1:2; \r\n— максимальная высота − 15 м \r\nШирина дамбы 24,5 м принята из условия производства работ по устрой￾ству противофильтрационного экрана с защитным и подстилающим слоями. \r\n5.3 ФИЛЬТРУЮЩАЯ ДАМБА\r\nСтвор дамбы расположен параллельно створу низовой водоудержи￾вающей дамбы на расстоянии 450 м вглубь хвостохранилища. \r\nДамба отсыпается из гравийно-галечникового грунта со вставками в по￾ниженных местах рельефа из фильтрующего скального грунта. \r\nФильтрующая дамба протяжённостью 2805,88 м имеет ширину по греб￾ню 15,0 м, заложение откосов верхового и низового 1:1,5 на участках, отсы￾панных из скального грунта, и 1:2 на участках, отсыпанных из гравийно￾галечникового грунта. Отметка гребня дамбы − 52,0 м. \r\nМаксимальная высота дамбы 13,0 м. \r\n5.4 РАЗДЕЛИТЕЛЬНАЯ ДАМБА\r\nРазделительная дамба выполняет функции северного участка вер￾ховой ограждающей дамбы на первую очередь строительства хвостохра￾нилища. \r\nПротяжённость дамбы 3507,41 м, ширина по гребню 15 м, заложение \r\nоткосов верхового и низового равно 1:2 (см. чертёж 3494-1-ГР, л.11). \r\nМаксимальная высота дамбы 8,0 м. Дамба относится к IV классу ГТС. \r\nДамба отсыпается из грунтов отвала вскрышных пород карьера \"Даль￾ний\" с послойным уплотнением (hсл. − 0,3 м) до γск. − не менее 1,65 т/м3\r\n. Кре￾пление гребня и откосов предусмотрено гравийно-галечниковым грунтом \r\nтолщиной слоя 1,0 м. По гребню дамбы на проезжей части автодороги пре￾дусмотрен выравнивающий слой из щебня (hсл. − 0,20 м).", "[стр. 22]\n3494.2-ПОС 22 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n5.5 ОБЩИЕ ПОЛОЖЕНИЯ\r\nДля сохранения температурного режима мохорастительный слой и \r\nторф в основании дамб не вынимается. \r\nУчитывая наличие в основании проектируемых дамб мёрзлых и талых \r\nгрунтов, дамбы хвостохранилища возводятся по второму принципу строи￾тельства. \r\nНа ограждающей верховой и низовой дамбах предусматривается элек￾троосвещение. \r\nДля отсыпки дамб хвостохранилища предлагается использовать грунты \r\nотвалов вскрыши карьера \"Дальний\", песчаные, песчано-гравийные и гра￾вийно-галечниковые грунты карьера \"Дальний\" и скальный грунт карьера \r\n\"Скалистый\". \r\n5.6 АВТОДОРОГИ\r\nНа площадке хвостохранилища предусматривается сеть автодорог. \r\n1. Автодороги по гребню круговой ограждающей дамбы, разделитель￾ной и фильтрующих дамб. \r\n2. Подъездная автодорога к хвостохранилищу (реконструкция сущест￾вующей автодороги от ТОФ на отстойник Хараелах на участке 1420 м). \r\n3. Подъездная автодорога к автодороге на карьер \"Скалистый\". \r\n4. Подъездные автодороги к наблюдательным скважинам в нижнем \r\nбьефе ограждающей дамбы. \r\n5.7 ДАМБЫ ОБВАЛОВАНИЯ\r\nДля отсыпки дамб обвалования предлагается использовать в качестве \r\nстроительного материала грунт отвалов вскрышных пород карьера \"Даль￾ний\". На верховом откосе предусматривается устройство противофильтра￾ционного экрана из намытых хвостов ТОФ. \r\nДлина дамб переменная − от 3,0 км до 9,3 км. Высота дамб − 3,0 м; ши￾рина по гребню 10 м, откосы 1:2.", "[стр. 23]\n3494.2-ПОС 23 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n5.8 НАМЫВНАЯ ДАМБА\r\nНамывная дамба, которая формируется в виде намывного отвала и \r\nподдерживается в процессе эксплуатации в мёрзлом состоянии, в условиях \r\nотсутствия напорного фронта может быть отнесена к IV классу гидротехни￾ческих сооружений. \r\n5.9 ЗДАНИЯ И СООРУЖЕНИЯ ХВОСТОВОГО СООРУЖЕНИЯ\r\nПульпонасосная станция (ПНС-1А), расширяемая часть ПНС-1, распо￾ложена в осях К-Л, 37-55 главного корпуса ТОФ. Отметка 0.00 пола пульпо￾насосной 96,85 м. \r\nОснащение пульпонасосной станции технологическим оборудованием \r\nпредусматривается в две очереди: к пуску пульпонасосной в эксплуатацию \r\n(второй пусковой комплекс строительства ТОФ) устанавливаются четыре \r\nнасоса Warman с соответствующей технологической обвязкой, во вторую \r\nочередь строительства ПНС устанавливаются еще четыре насоса Warman. \r\nУзел переключения − наземное здание 12х24 м2\r\n, высотой 10 м, распо￾ложен в нижнем бьефе верховой ограждающей дамбы хвостохранилища. \r\nОтметка нуля — 72,0 м. \r\nПлавучие насосные установки и насосная станция оборотной воды по \r\nнадёжности относятся ко II категории. \r\nПредусматривается установить две плавучие насосные установки. \r\nНасосная станция оборотной воды расположена в нижнем бьефе вер￾ховой ограждающей дамбы по левому борту хвостохранилища, на расстоя￾нии 80 м от подошвы дамбы. Насосная станция наземного типа, размером в \r\nплане 30х19,5 м, отметка нуля 51 м. \r\nВ насосной устанавливаются три насоса Warman 150PF-PCH, обеспе￾чивающие резерв и подачу оборотной воды на промплощадку во второй и \r\nтретий пусковые комплексы как в летний, так и в зимний периоды.", "[стр. 24]\n3494.2-ПОС 24 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n6. СВЕДЕНИЯ О ВОЗМОЖНОСТИ ИСПОЛЬЗОВАНИЯ МЕСТНОЙ \r\nРАБОЧЕЙ СИЛЫ ПРИ ОСУЩЕСТВЛЕНИИ СТРОИТЕЛЬСТВА \r\nОсновной объем строительно-монтажных работ выполняет генподряд￾чик своими силами. Обеспечение строительства кадрами осуществляется \r\nгенподрядной и субподрядными организациями, участвующими в строи￾тельстве. \r\n7. ПЕРЕЧЕНЬ МЕРОПРИЯТИЙ ПО ПРИВЛЕЧЕНИЮ ДЛЯ \r\nОСУЩЕСТВЛЕНИЯ СТРОИТЕЛЬСТВА КВАЛИФИЦИРОВАННЫХ \r\nСПЕЦИАЛИСТОВ, В ТОМ ЧИСЛЕ ДЛЯ ВЫПОЛНЕНИЯ РАБОТ \r\nВАХТОВЫМ МЕТОДОМ \r\nНа специальные монтажные работы привлекаются специализирован￾ные субподрядные организации. Вопрос о найме специалистов решается \r\nгенподрядной и субподрядными организациями. \r\nНа специальные монтажные работы привлекаются специализирован￾ные субподрядные организации. Вопрос о найме специалистов решается \r\nгенподрядной и субподрядными строительными организациями, имеющие \r\nопыт строительства гидротехнических сооружений. Подрядные строитель￾ные организации должны иметь необходимую лицензию, собственную \r\nстроительную базу и соответствующее хозбытовое обеспечение в период \r\nвыполнения строительно-монтажных работ. Работы не ведутся вахтовым \r\nметодом.\r\n8.ХАРАКТЕРИСТИКА ЗЕМЕЛЬНОГО УЧАСТКА, \r\nПРЕДОСТАВЛЕННОГО ДЛЯ СТРОТЕЛЬСТВА, ОБОСНОВАНИЕ \r\nНЕОБХОДИМОСТИ ИСПОЛЬЗОВАНИЯ ДЛЯ СТРОИТЕЛЬСТВА ЗЕ￾МЕЛЬНЫХ УЧАСТКОВ ВНЕ ЗЕМЕЛЬНОГО УЧАСТКА, \r\nПРЕДОСТАВЛЕННОГО ДЛЯ СТРОИТЕЛЬСТВА ОБЪЕКТА \r\nПроект границы земельного отвода под сооружения хвостохранилища и \r\nкоммуникационного коридора труб ТОФ − хвостохранилище ТОФ и Поста￾новления Администрации города Норильска Красноярского края \"Об утвер-", "[стр. 25]\n3494.2-ПОС 25 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nждении границ земельных участков и предоставлении земельных участков\" \r\nпод строительство хвостохранилища и трассы трубопроводов №2608 от \r\n13.12.2006 г. и №2707 от 23.07.2010 г. \r\nЗемельные участки, отведённые Управлением имущества Администра￾ции города Норильска под строительство сооружений хвостового хозяйства \r\nТОФ, предоставлены из земель промышленности, энергетики, транспорта, \r\nсвязи, радиовещания, телевидения, информатики, земель для обеспечения \r\nкосмической деятельности, земель обороны, безопасности и земель иного \r\nспециального назначения. \r\nЗемельные участки под строительство сооружений хвостового хозяйст￾ва переданы ЗФ ОАО \"ГМК \"НН\" во временное пользование. \r\nКадастровые паспорта земельных участков и договора на аренду зе￾мельных участков под строительство хвостохранилища и трассы трубопро￾водов от ТОФ до хвостохранилища № 6509 от 30 июля 2010 г. и №4607 от \r\n12 января 2007 г. приведены в приложении \"Б\".\r\n9. ОПИСАНИЕ ОСОБЕННОСТЕЙ ПРОВЕДЕНИЯ РАБОТ В \r\nУСЛОВИЯХ ДЕЙСТВУЮЩЕГО ПРЕДПРИЯТИЯ, В МЕСТАХ \r\nРАСПОЛОЖЕНИЯ ПОДЗЕМНЫХ КОММУНИКАЦИЙ, ЛИНИЙ \r\nЭЛЕКТРОПЕРЕДАЧИ И СВЯЗИ \r\nВсе строительно-монтажные работы по возведению объектов хвостово￾го хозяйства ведутся на свободной от застройки территории. Описание осо￾бенностей проведения работ в условиях действующего предприятия не тре￾буется.", "[стр. 26]\n3494.2-ПОС 26 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n10. ОБОСНОВАНИЕ ПРИНЯТОЙ ОРГАНИЗАЦИОННО￾ТЕХНОЛОГИЧЕСКОЙ СХЕМЫ, ОПРЕДЕЛЯЮЩЕЙ \r\nПОСЛЕДОВАТЕЛЬНОСТЬ ВОЗВЕДЕНИЯ ЗДАНИЙ И СООРУЖЕНИЙ, \r\nИНЖЕНЕРНЫХ И ТРАНСПОРТНЫХ КОММУНИКАЦИЙ, \r\nОБЕСПЕЧИВАЮЩИЙ СОБЛЮДЕНИЕ УСТАНОВЛЕННЫХ В \r\nКАЛЕНДАРНОМ ПЛАНЕ СТРОТЕЛЬСТВА СРОКОВ ЗАВЕРШЕНИЯ \r\nСТРОИТЕЛЬСТВА \r\nСтроительно-монтажные работы производятся по разработанным ген￾подрядчиком проектам производства работ (ППР) с выполнением требова￾ний и указаний соответствующих глав СНиП ч. III , общих нормативных до￾кументов по организации строительного производства, а также правил тех￾ники безопасности (СНиП 12-04-2002) и пожарной безопасности в строи￾тельстве (ППБ01-03). \r\nПри производстве отдельных видов работ следует руководствоваться \r\nизданными типовыми технологическими картами на эти работы, а также тех￾нологическими картами, разработанными в ППР. \r\nСтроительно-монтажные работы планируется производить круглого￾дично, оставляя сроки выполнения работ нормативными, без изменений, за \r\nсчет применения в зимних условиях дополнительных технических меро￾приятий (навесное оборудование на землеройных машинах, электропрогре￾вов и метод «термоса» при бетонировании монолитных конструкций и др.). \r\nОбъемно-планировочные, компоновочные и конструктивные решения \r\nобъектов не содержат сложной и неосвоенной технологии производства от￾дельных видов работ. \r\nРекомендации по организации строительства разработаны для усло￾вий, когда Генподрядчик и субподрядные организации имеют всю необхо￾димую строительную технику, а также обеспечены рабочими кадрами и фи￾нансированием для выполнения работ в планируемые сроки. \r\n10.1 ОБОСНОВАНИЕ МЕТОДОВ ПРОИЗВОДСТВА ОСНОВНЫХ СТРОИТЕЛЬНО￾МОНТАЖНЫХ РАБОТ\r\nОписание методов производства основных строительно-монтажных ра￾бот приводится в объеме, необходимым для обоснования выбора типов \r\nприменяемых строительных механизмов и оборудования, а также для опре￾деления стоимости строительства на стадии проекта, главным образом, в", "[стр. 27]\n3494.2-ПОС 27 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nчасти земляных работ. Методы строительства решены в соответствии с \r\nпринципами передовой технологии строительного производства при строгом \r\nсоблюдении техники безопасности ведения работ. \r\nПри разработке методов производства работ учитывалось: \r\n― наличие и состав парка строительных машин; \r\n― возможность подвоза строительных конструкций автотранспортом \r\nнепосредственно к месту монтажа. \r\nПринято круглогодичное производство строительно-монтажных работ \r\nподрядным способом и силами генподрядной организации с привлечением \r\nсубподрядных организаций в 3 смены по 8 часов. \r\nСтруктура строительной организации - прорабский участок. \r\nСнабжение строительными конструкциями, материалами и изделиями \r\nобеспечивается подрядчиками. \r\nВ процессе строительства необходимо организовать контроль и прием￾ку поступающих конструкций, деталей и материалов. \r\nСтроительство ведется в два этапа. \r\nПервый - выполнение комплекса подготовительных работ, включающих \r\nв себя: \r\n― обустройство и подготовка стройплощадки; \r\n― создание общеплощадочного складского хозяйства; \r\n― устройство временных площадок; \r\n― устройство площадок укрупнительной сборки; \r\n― возведение временных сооружений; \r\n― осуществление мероприятий по обеспечению охраны труда и окру￾жающей природной среды; \r\n― инженерная подготовка стройплощадки (прокладка временных се￾тей энергоснабжения для освещения рабочих мест и производства \r\nстроительно-монтажных работ, подключения строительных машин, \r\nпланировка территории, обеспечивающая временный водоотвод \r\nповерхностных вод, устройство временных подъездов и дорог, ис￾пользуемых на период строительства); \r\n― организация охраны и связи на строительной площадке. \r\nВ подготовительный период необходимо проведение следующих обя￾зательных мероприятий: \r\n― до начала выполнения строительно-монтажных работ, в том числе \r\nподготовительных работ на объекте Заказчик обязан получить в ус￾тановленном порядке разрешение на выполнение строительно-", "[стр. 28]\n3494.2-ПОС 28 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nмонтажных работ. Выполнение работ без указанного разрешения \r\nзапрещается; \r\n― строительство должно вестись в технологической последовательно￾сти в соответствии с календарным планом с учетом обоснованного \r\nсовмещения отдельных видов работ; \r\n― к основным работам по строительству объекта или его части раз￾решается приступать только после устройства необходимых ограж￾дений строительной площадки (охранных, защитных или сигналь￾ных) и создания разбивочной геодезической основы. \r\nДо начала возведения сооружений необходимо произвести расчистку \r\nплощадки, срезку и складирование используемого для рекультивации зе￾мель растительного слоя грунта в специально отведенных местах. \r\nОрганизацию строительной площадки выполнить в соответствии со \r\nстройгенпланом: \r\n― размещение временных зданий и сооружений (мобильных, инвен￾тарных) предусмотреть вне опасных зон. Обеспечение персонала \r\nсанитарно-бытовым обслуживанием и питанием осуществляется в \r\nмобильных зданиях подрядчика; \r\n― для освещенности территории строительной площадки и внутрипо￾строечных работ обеспечить нормативную освещенность (не менее \r\n2 лк); \r\n― электроснабжение до начала работы временной ПС 110/35/10 кв \r\n(ввод по предварительному графику –III квартал 2012 г) от дизель￾ных электростанций; \r\n― сжатый воздух –использование компрессорных станций, передвиж￾ных компрессоров; \r\n― получение кислорода- от передвижной кислородной станции; \r\n― ацитилен доставляется в баллонах, автотранспортом; \r\n― топливо доставляется спецавтотранспортом; \r\n― водоснабжение для технических нужд строительства-по временной \r\nсхеме из скважин водозабора; \r\n― питьевое водоснабжение и водоснабжение для хозяйственно￾бытовых нужд осуществляется путем доставки на строительную \r\nплощадку воды, имеющий сертификат сан. Эпид. Надзора (для пи￾тья –бутилированная, для санитарно-бытовых и противопожарных \r\nнужд –заполнение резервуаров воды", "[стр. 29]\n3494.2-ПОС 29 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n― строительный мусор вывозить на санкционированные свалки. Вы￾возку строительного мусора осуществлять контейнерами и обору￾дованными самосвалами. Бытовой мусор также вывозить контейне￾рами на спецплощадки. \r\nВторой - основной период, включающий: \r\n― геодезическую съемку и разбивку осей зданий и сооружений на ме￾стности; \r\n― оформление разрешения на производство работ; \r\n― возведение зданий и сооружений. \r\nВ случаи выполнение работ в зимних условиях следует осуществлять в \r\nсоответствии с требованиями нормативных документов: СНиП 3.02.01-87, \r\nСНиП 12.03-2001, часть 1 и СНиП 12.04-2002, часть 2.Способы производст￾ва работ обосновываются в ППР, где, исходя из возможностей строитель￾ной организации и особенностей площадки строительства, принимается \r\nрешение по способу ведения работ. \r\n10.2 ОРГАНИЗАЦИОННЫЕ ВОПРОСЫ\r\nПри организации строительства необходимо: \r\n— отобрать существующие или разрабатывать новые устройства и \r\nгрузозахватные приспособления для безопасного выполнения ра￾бот; \r\n— предусмотреть решения по технике безопасности, требующие про￾ектной разработки: крепление стенок земляных выемок, временное \r\nкрепление конструкций; \r\n— устроить временное заземление (при необходимости); \r\n— решить вопросы по созданию безопасных условий работы на высо￾те, в зоне воздушных электрических линий и подземных коммуника￾ций, при эксплуатации строительных машин и электрических уста￾новок; \r\n— при отсутствии в документации специальных требований, предель￾ные отклонения геометрических параметров конструкций, посту￾пивших на монтаж, должны соответствовать 4-му классу точности; \r\n— разгрузку конструкций производить на специально предусмотрен￾ные площадки складирования строительных материалов. Расстоя￾ние между штабелями конструкций должно быть не менее 1 м, \r\nстроительные материалы в штабеля складываются с применением", "[стр. 30]\n3494.2-ПОС 30 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n“прокладок” и “подкладок” или складируются в специальные кассе￾ты; \r\n— подачу металлоконструкций в зону монтажа осуществлять авто￾транспортом с площадок укрупненной сборки; \r\n— определить расположение постоянных и временных транспортных \r\nдорог, площадок и помещений для складирования материалов, мест \r\nприемки раствора и бетона, расположение мест стоянки строитель￾ных машин и механизированных установок; \r\n— определить зоны, опасные для нахождения людей (вблизи мест пе￾ремещения грузов, расстояний от неогражденных неизолированных \r\nчастей электроустановок, линий воздушных электропередач); \r\n— предусмотреть в ППР мероприятия, исключающие перемещение гру￾зов над существующими временными сооружениями, а также прибли￾жение к ним вращающихся частей механизмов на расстоянии менее \r\n2,0 м; \r\n— при производстве работ в зимних условиях руководствоваться требо￾ваниями СНиП 3.03.01-87 “Несущие и ограждающие конструкции” и \r\nСНиП 3.02.01-87 “Земляные сооружения, основания и фундаменты”; \r\n— соблюдать правила хранения конструкций на открытом воздухе, \r\nконструкции не должны соприкасаться с грунтом и на них не должна \r\nзастаиваться вода; \r\n— на протяжении строительства и монтажа необходимо оформить ак￾ты на скрытые и сварочные работы . \r\n11. ПЕРЕЧЕНЬ ВИДОВ СТРОИТЕЛЬНЫХ И МОНТАЖНЫХ РАБОТ, \r\nОТВЕТСТВЕННЫХ КОНСТРУКЦИЙ, УЧАСТКОВ СЕТЕЙ \r\nИНЖЕНЕРНО-ТЕХНИЧЕСКОГО ОБЕСПЕЧЕНИЯ, ПОДЛЕЖАЩИХ \r\nОСВИДЕТЕЛЬСТВОВАНИЮ С СОСТАВЛЕНИЕМ \r\nСООТВЕТСВУЮЩИХ АКТОВ ПРИЕМКИ ПЕРЕД ПРОИЗВОДСТВОМ \r\nПОСЛЕДУЮЩИХ РАБОТ И УСТРОЙСТВОМ ПОСЛЕДУЮЩИХ \r\nКОНСТРУКЦИЙ. \r\nПри устройстве временных сооружений (котлованов, траншей) прове￾ряют горизонтальную привязку, правильность разбивки осей, вертикальные \r\nотметки. Случайные переборы грунта, то есть снятие его ниже проектных \r\nотметок, заполняют грунтом, однородным вынутому, с последующим его уп-", "[стр. 31]\n3494.2-ПОС 31 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nлотнением, а в особенно ответственных случаях – бетоном класса В5. На \r\nзаконченные части земляных сооружений составляют акты на скрытые ра￾боты, которые вместе с рабочими чертежами, результатами лабораторных \r\nиспытаний грунтов, журналами работ и другими документами предъявляют \r\nприемной комиссии во время технической приемки-сдачи объекта. \r\nПриемка насыпей и выемок заключается в проверке в натуре положе￾ния земляного сооружения, его геометрических размеров, отметок дна, уст￾ройства водоотвода, степени уплотнения грунтов. В процессе принятия ра￾бот при планировании площадок и территорий следует удостовериться в \r\nтом, что отметки и уклоны отвечают проектным, нет переувлажненных уча￾стков и местных просадок грунта. Принимая котлованы и траншеи, прове￾ряют соответствие проекта их размеров, отметок, качества грунта в основа￾нии, правильность установки креплений. \r\nПеречень видов работ, на которые составляются акты на скрытые ра￾бот и акты промежуточной приемки. \r\nЗемляные работы:\r\n1. Устройство естественных оснований под земляные сооружения, фун￾даменты, трубопроводы в котлованах, траншеях или на поверхности земли. \r\n2. Выполнение предусмотренных проектом или назначаемых по ре￾зультатам осмотра вскрытых оснований инженерных мероприятий по закре￾плению грунтов и подготовке основания. \r\n3. Конструкции, входящие в тело земляного сооружения; установлен￾ные проектом границы зон раскладки грунтов с отличающимися физико￾механическими характеристиками. \r\n4. Элементы дренажей (дренажные слои и их основания, трубопроводы \r\nи их обсыпка); подстилающие слои при установке контрольно￾измерительной аппаратуры. \r\n5. Обратные засыпки выемок в местах пересечения с дорогами, тротуа￾рами и иными территориями с дорожными покрытиями. \r\n6. Мероприятия, необходимые для возобновления работ при перерывах \r\nв ведении работ более месяца, при консервации и расконсервации работ. \r\nУстройство оснований и фундаментов:\r\n1. устройство искусственных оснований под фундаменты, включая дно \r\nкотлованов. \r\n2. акт на устройство фундаментов под оборудование. \r\n3. бурение всех видов скважин; \r\nБетонные работы:", "[стр. 32]\n3494.2-ПОС 32 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n1. Армирование железобетонных конструкций. \r\n2. Установка закладных частей. \r\n3. Антикоррозионная защита закладных деталей и сварных соединений \r\n(швов, накладок). \r\n4. Устройство опалубки конструкций с инструментальной проверкой от￾меток и осей. \r\nМонтаж стальных конструкций:\r\n1. Предварительная подготовка поверхностей, защищаемых от агрес￾сивного воздействия среды. \r\n2. Установка стальных конструкций, скрывающихся в процессе произ￾водства последующих работ. \r\n3. Опирание и анкеровка несущих металлических конструкций. \r\n4. Защита строительных конструкций и закладных деталей от корро￾зии. \r\n5. Установка анкерных болтов. \r\n6. Монтаж сопряжений на высокопрочных болтах. \r\n7. Акты на сварочные работы. \r\n8. Акты на гидравлические испытание трубопроводов.\r\nМонтаж легких ограждающих конструкций\r\n1. акты на монтаж оконных, дверных блоков (в условиях строительной \r\nплощадки); \r\n2. акты на герметизацию по периметру дверных, оконных коробок. \r\nПредъявляемая при сдаче работ техническая документация должна \r\nсодержать: \r\n1. Ведомости существующих постоянных реперов. \r\n2. Акты геодезической разбивки зданий и сооружений.\r\n3. Рабочие чертежи сооружений с вынесенными в процессе производ￾ства работ и согласованными с проектной организацией и заказчи￾ком изменениями. \r\n4. Журнал работ. \r\n5. Акты освидетельствования скрытых работ или журналы поэтапной \r\nприемки работ.", "[стр. 33]\n3494.2-ПОС 33 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПри возведении линейно-протяженных земляных сооружений, особен￾но насыпей и выемок для дорог, заключительный этап контроля качества и \r\nсдача-приемка осуществляются на законченном строительством участке. \r\nСдача-приемка работ производится на основании проверки наличия \r\nтехнической документации, выборочной проверки качества выполнения ра￾бот и геометрических размеров земляных сооружений, актов приемки сры￾тых видов работ. \r\n12. ТЕХНОЛОГИЧЕСКАЯ ПОСЛЕДОВАТЕЛЬНОСТЬ РАБОТ ПРИ \r\nВОЗВЕДЕНИИ ОБЪЕКТОВ КАПИТАЛЬНОГО СТРОИТЕЛЬСТВА ИЛИ \r\nИХ ОТДЕЛЬНЫХ ЭЛЕМЕНТОВ \r\nДо начала производства работ заказчик обязан оформить и передать \r\nподрядчику разрешение на производство работ (передать стройплощадку и \r\nфронт работ по акту) и выдать согласованный в полном объеме проект (ра￾бочие чертежи, необходимые согласования, сметы и пр.) с указанием мест \r\nподключения временных инженерных (постоянных) сетей и разрешения на \r\nподключения эксплуатирующих организаций (заключить договора). \r\n Для обеспечения своевременной подготовки и соблюдения технологи￾ческой последовательности строительства проектом предусматривается \r\nдва периода строительства – подготовительный и основной. \r\n12.1 ТЕХНОЛОГИЧЕСКАЯ ПОСЛЕДОВАТЕЛЬНОСТЬ РАБОТ\r\nСтроительно-монтажные работы сооружений хвостового хозяйства \r\nприемущественно -земляные работы. Земляные работы выполняют в соот￾ветствии с правилами производства и приемки работ, приведенными в \r\nСНиП 3.02.01-87 «Земляные сооружения. Основания и фундаменты». При \r\nпроизводстве земляных работ следует обходиться минимальным количест￾вом землеройных машин, обеспечив их достаточную маневренность, сосре￾дотачивая при необходимости максимум техники на особо важном в данный \r\nпериод строительства направлении. \r\nВ процессе земляных работ необходимо организовать постоянный тех￾нический надзор за состоянием грунта и соблюдением техники безопасно￾сти при производстве работ. \r\nДля сокращения продолжительности строительства проектом преду￾сматривается максимально возможное совмещение строительно-", "[стр. 34]\n3494.2-ПОС 34 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nмонтажных работ в составе объектного потока на каждом объекте комплек￾са. \r\nСтепень совмещения, последовательность и сроки выполнения строи￾тельно-монтажных работ устанавливаются в календарном плане производ￾ства работ, который, согласно п. 6.3 МДС-12-46.2008, разрабатывается в \r\nсоставе проекта производства работ (ППР) подрядной организацией. \r\n12.1.1 Земляные работы \r\nЗемляные работы должны выполняться по разработанным и согласо￾ванным проектам производства работ в строгом соответствии с требова￾ниями СНиП 3.02.01-87 «Земляные сооружения, основания и фундаменты». \r\nДо начала земляных работ по отрывке котлованов под проектируемые \r\nздания должны быть произведены следующие работы: \r\n― создана геодезическая разбивочная основа на строительной площад￾ке; \r\n― осуществлен вынос в натуру от пунктов геодезической разбивочной \r\nосновы осей на строительной площадке для разработки котлованов; \r\n― выполнена разметка габаритов проектируемых котлованов, траншей \r\nи по их периметру установлено сигнальное ограждение; \r\n― выполнено временное электроснабжение с устройством электроос￾вещения строительной площадки; \r\n― решены вопросы по организации мест складирования грунта, непри￾годного для обратных засыпок, а также грунта пригодного для обратных за￾сыпок. \r\n― оформлены акты о готовности площадки для начала земляных работ. \r\nДля механизированной разработки грунта в котлованах и траншеях ре￾комендуется использовать экскаваторы с ковшом вместимостью 0,5-1,0 м3. \r\nГрунт, разрабатываемый в котлованах, погружается на автотранспорт и \r\nвывозится в резерв. Разработка грунта ниже уровня грунтовых вод про￾изводится под защитой строительного водопонижения. \r\nНедобор грунта при разработке экскаватором 20см. Доработка грунта \r\nвручную производится непосредственно перед устройством бетонной подго￾товки. \r\nДо полного завершения работ “нулевого” цикла необходимо выполнять \r\nмероприятия по предотвращению промерзания грунта, безопасному скла￾дированию материалов и безопасному размещению строительной техники \r\nвблизи котлована.", "[стр. 35]\n3494.2-ПОС 35 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nЗасыпка грунта в пазухи производится: на относительно свободных \r\nплощадках – при помощи бульдозера. \r\nУплотнение грунта в обратных засыпках производится: в стесненных \r\nместах - ручными и подвесными трамбовками, на относительно свободных \r\nплощадках - самоходными катками весом 10 т. \r\nВ местах обратных засыпок, где невозможно обеспечить качественное \r\nуплотнение грунта, полученного при разработке котлована или траншеи, об￾ратную засыпку пазух необходимо производить только песком, шлаком или \r\nщебнем. \r\nДля механизации земляных работ рекомендуется применять современ￾ные землеройные машины: \r\n― бульдозеры мощностью 79-132 кВт – для перемещения грунта; \r\n― специальные машины для рыхления и разработки мерзлых грунтов; \r\n― экскаваторы с ковшами вместимостью 0,5-1,0 м3 – для разработки \r\nгрунта в котлованах и траншеях; \r\n― самоходные катки весом 8-25 т – для уплотнения грунта при обратных \r\nзасыпках и устройстве искусственных оснований; \r\n― автосамосвалы грузоподъемностью 15-45т - для перевозки грунта. \r\n12.1.2 Устройство бетонных и железобетонных конструкций \r\nК устройству подземных бетонных и железобетонных конструкций не￾обходимо приступать после сдачи по акту котлованов и оформления актов \r\nна скрытые работы. \r\nОпалубка для устройства монолитных конструкций применяется, в ос￾новном, инвентарная, щитовая, разборно-переставная, многоразового при￾менения. Установленная опалубка принимается по акту на скрытые работы. \r\nНагрузки на опалубку следует рассчитывать в соответствии с требова￾ниями СНИП 3.03.01-87. \r\nАрматура применяется, в основном, вязаная и заготавливается в по￾строечных условиях. Армирование конструкций выполняется путем установ￾ки отдельных стержней с креплением их вязаной проволокой. \r\nТранспортирование и складирование арматуры выполняется в соответ￾ствии с ГОСТ 7566-81. \r\nЗаготовка арматурных стержней производится на специально оборудо￾ванном арматурном участке. Арматурный участок располагается на строи￾тельной площадке под навесом, оснащается оборудованием для правки, \r\nгнутья, резки и сварки.", "[стр. 36]\n3494.2-ПОС 36 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nАрматура монтируется в последовательности, обеспечивающей ее пра￾вильное положение и закрепление. Приемка смонтированной арматуры \r\nоформляется актом на скрытые работы. Для обеспечения защитного слоя \r\nбетона устанавливаются специальные фиксаторы. Для прохода по арматуре \r\nпредусмотреть устройство трапов. К месту установки арматура подается \r\nкраном и вручную. \r\nБетонная смесь на стройплощадку подается автобетоновозами. Уста￾новка опалубки и армокаркасов производится при помощи монтажных кра￾нов грузоподъемностью 10-25т. Подача бетонной смеси к месту укладки \r\nосуществляется при помощи автобетоноукладчиков типа БН-80-20М или \r\nспособом «кран-бадья» с применением бадьей типа БПВ-0,5, БПВ-1,0, БПВ￾1,6 (объемом от 0,5 до 1,6 м3). Для подачи бадьей с бетоном к месту его ук￾ладки используются монтажные краны грузоподъемностью 10-25 т. \r\nУплотнение бетонной смеси производится вибраторами.\r\nПри уплотнении бетонной смеси не допускается опирание вибраторов \r\nна арматуру и закладные изделия, тяжи и другие элементы крепления опа￾лубки. Глубина погружения глубинного вибратора в бетонную смесь должна \r\nобеспечивать углубление его в ранее уложенную бетонную смесь на 5-10 \r\nсм. Шаг перестановки глубинных вибраторов не должен превышать полу￾торного радиуса их действия. \r\nОптимальный режим выдерживания бетона: температура +18ºС, влаж￾ность 90%. \r\nКонтроль качества поступающей и уложенной бетонной смеси осуще￾ствляет строительная лаборатория в соответствии с ГОСТ 10180-78. \r\nВ начальный период твердения бетон необходимо защищать от попа￾дания атмосферных осадок, потерь влаги и поддерживать температурно￾влажный режим с созданием условий, обеспечивающий нарастание его \r\nпрочности. \r\nМероприятия по уходу за бетоном, порядок и сроки их проведения, сро￾ки распалубки устанавливаются в ППР. \r\nВсе работы по устройству бетонных и железобетонных конструкций \r\nдолжны выполняться по рабочим чертежам в соответствии с требованиями \r\nСНиП 3.03.01-87 «Несущие и ограждающие конструкции». \r\nУстройство и монтаж железобетонных конструкций разрабатывается в \r\nпроекте производства работ (ППР) специализированной организацией вы￾полняющей эти работы.", "[стр. 37]\n3494.2-ПОС 37 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nНа все виды скрытых работ составляются соответствующие акты. Ве￾дется журнал бетонных работ. \r\nВсе работы по устройству монолитных железобетонных конструкций \r\nвыполнять в соответствии с СНиП 3.03.01-87, СНиП 3.01.03-84, СНиП 12-03-\r\n01, СНиП 12-04-02, СНиП 12-136-03, ПБ 10-382-00, ППБ 03-01, СанПиН \r\n2.2.3.1384-03. \r\nОбмазочную гидроизоляцию поверхностей подземных конструкций вы￾полнять в соответствии с СНиП 3.04.03-85 “Защита строительных конструк￾ций от коррозии”. Обмазочная изоляция боковых и горизонтальных частей \r\nжелезобетонных конструкций выполняется вручную с применением малой \r\nмеханизации. \r\n12.1.3 Монтаж строительных конструкций \r\nМонтаж строительных конструкций предусматривается осуществить с \r\nиспользованием монтажных кранов различных типов (колесных, гусеничных \r\nгрузоподъемностью от 25 до 100 т. \r\nЭлементы сборных конструкций должны иметь маркировку и паспорт. \r\nМонтаж стальных конструкций необходимо производить в последова￾тельности, обеспечивающей устойчивость и неизменность конструкций на \r\nвсех стадиях монтажа. \r\nОсновные элементы стальных конструкций, определяющие геометри￾ческое положение (колонны и пр.), должны быть установлены сразу же на \r\nпроектные оси и ряды в наиболее близкое к проектному положению (по \r\nуровню и отвесу). \r\nМонтаж стальных конструкций необходимо производить согласно про￾екту производства работ (ППР и ППРк), разработанному специализирован￾ной организацией. \r\n12.1.4 Монтаж технологического оборудования \r\nРаботы по монтажу технологического оборудования выполнять в соот￾ветствии с требованиями СНиП 3.05.05-84 «Технологическое оборудование \r\nи технологические трубопроводы». Для монтажа оборудования использо￾вать подъемно-транспортные механизмы, задействованные на строительно￾монтажных работах. Передачу оборудования под монтаж осуществлять с \r\nприобъектных складов.", "[стр. 38]\n3494.2-ПОС 38 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nРазработка мероприятий, направленных на обеспечение сохранения \r\nоборудования в период хранения его на приобъектных складах (до переда￾чи в монтаж), возлагается на Заказчика. \r\nФундаменты под оборудование должны быть приняты по актам, подпи￾санным представителями строительных организаций, а также представите￾лем Заказчика. \r\nДо начала работ должны быть испытаны все грузоподъемные меха￾низмы и такелажные средства, используемые на монтаже. На участках, \r\nгде монтаж оборудования будет осуществляться с применением такелаж￾ных средств, в местах приложения монтажных нагрузок на строительные \r\nконструкции должны быть выполнены мероприятия по усилению последних. \r\nМонтаж специализированного оборудования необходимо вести в соот￾ветствии с проектом разработчика оборудования. \r\n12.2 ТЕХНОЛОГИЧЕСКАЯ ПОСЛЕДОВАТЕЛЬНОСТЬ ВОЗВЕДЕНИЯ НАСОСНЫХ\r\nРаботы по строительству возведению насосных выполняются после \r\nотрывки котлована. Разработка грунта котлована производится экскавато￾ром обратная лопата с ёмкостью ковша 0,5 м3\r\n, 1,25 м3\r\n с погрузкой в автоса￾мосвалы, зачистка дна котлована бульдозером и вручную. Обратная засып￾ка котлована в пределах площади застройки здания и пазух котлована осу￾ществляется среднезернистым песком с тщательным послойным уплотне￾нием. Водоотвод грунтовых и поверхностных вод, поступающих в котлован \r\nпроизводится насосами на рельеф или в водоотводящие канавы сечением \r\n0,5х0,3х0,5, идущие с уклоном 0,003 к колодцам-зумпфам. Дно колодца \r\nдолжно быть ниже дна котлована на 1-1,2м.\r\nМесто сброса и метод уточняется в ППР. \r\nМонтаж опалубки и арматуры производится стреловыми кранами г/п \r\n16,0 т и 25,0 т. Бетонирование осуществляется автобетононасосом типа \r\nАБН-60, подвоз бетона производится автобетоновозами. При устройстве \r\nмонолитных ж.б. конструкций применяется унифицированная сборно￾разборная опалубка (типа «Тяжстрой-78» или ей подобные). \r\nМонтаж колонн, стен и перегородок ведётся с унифицированных под￾мостей. Подача материалов, конструкций и раствора осуществляется стре￾ловыми кранами г/п 16,0 т и 25,0 т. \r\nПодача материалов для устройства кровли осуществляется мачтовым \r\nподъёмником г/п 0,4-1,0 т. или стреловыми кранами.", "[стр. 39]\n3494.2-ПОС 39 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n12.3 ПРОИЗВОДСТВО РАБОТ В ЗИМНИХ УСЛОВИЯХ\r\nВыполнение работ в зимних условиях следует осуществлять в соответ￾ствии с требованиями нормативных документов СНиП 3.02.01-87, СНиП \r\n12.03-2001,Часть 1. и СНиП 12.04-2002, часть 2. \r\n12.3.1 Земляные работы \r\nЗемляные работы выполняют в соответствии с правилами производст￾ва и приемки работ, приведенными в СНиП 3.02.01-87 \"Земляные сооруже￾ния, основания и фундаменты\". \r\nРазработка мерзлого грунта ведется механизированным способом с \r\nприменением как обычных землеройных и землеройно-транспортных ма￾шин, так и машин, оборудованных специальными рабочими органами. \r\nПри промерзании грунта больше чем на 1 метр и при разработке вы￾емок рекомендуется предварительное рыхление грунта, а также примене￾ние машины для разрыхления грунта в комплекте с экскаватором. \r\nПри промерзании грунта до 1 метра и при больших объемах работ раз￾рыхление грунта можно производить с помощью врубового механизма, ус￾тановленного на тракторе или с помощью гидромолотов навешанных на экс￾каваторы. \r\nНельзя допускать разрывов во времени как при производстве земляных \r\nработ, так и при последующем производстве бетонных и других работ. \r\nГрунты, подлежащие разработке в зимнее время, предохраняют от про￾мерзания предварительным, глубоким рыхлением до 1,5 метров. \r\nОбразующаяся при рыхлении гребенчатая поверхность задерживает \r\nснег, который в свою очередь защищает от промерзания. Глубокое рыхле￾ние рекомендуется применять для малосвязных и гравелистых грунтов. \r\n12.3.2 Бетонные и железобетонные работы \r\nВ зимнее время устройство монолитных железобетонных конструкций \r\nдолжно выполнять по специально разработанным технологическим картам в \r\nсоставе ППР. \r\nВ этих картах должны быть отражены: \r\n― особенности технологии приготовления и транспортирования бетон￾ной смеси, обеспечивающие получение заданной температуры этой смеси у \r\nместа ее укладки в конструкцию; \r\n― требуемая прочность бетона к концу выдерживания и моменту распа￾лубливания;", "[стр. 40]\n3494.2-ПОС 40 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n― способы и температурно-влажностные режимы выдерживания бетона; \r\n― данные о материале опалубки с указанием теплоизоляционных пока￾зателей; \r\n― потребность воды, энергии, оборудования и специальных материалов; \r\n― схема размещения скважин и наименование устройств для изменения \r\nтемпературы бетона; \r\n― при применении электротермообработки бетона дополнительно ука￾зывается схема размещения и подключения электродов или электронагрева￾телей, требуемые электрическая мощность, напряжение и сила тока, тип \r\nпонижающего трансформатора, сечение и длина проводов; \r\n― сроки и порядок распалубливания и загружения конструкций; \r\n― особенности техники безопасности при производстве работ. \r\n12.3.3 Монтаж строительных конструкций \r\nПри монтаже металлических конструкций в условиях отрицательной \r\nтемпературы необходимо в ППР разрабатывать меры по снижению опасно￾сти производства работ, в том числе: \r\n― предмонтажное усиление конструкций; \r\n― своевременная установка монтажных и постоянных связей; \r\n― тщательное временное закрепление монтируемых конструкций и их \r\nвыверка; \r\n― очистка и сушка стыкуемых поверхностей и выполнение постоянных \r\nсоединений; \r\n― при температуре воздуха ниже минус 15ºС предварительно прогревать \r\nметалл в зоне стыков при резке и сварке; \r\n― применят безвыверочный метод монтажа; \r\n― контролировать сварные швы более тщательно. \r\nКровельные работы в условиях низких температур выполняются при \r\nтемпературе наружного воздуха до минус 30ºС. \r\nНе разрешается выполнять кровельные работе при гололедице, снего￾паде, тумане, сильном ветре. \r\nДо начала отделочных работ в зимнее время должны быть произведе￾ны следующие работы: \r\n― выполнена защита отделываемых помещений от атмосферных осад￾ков; \r\n― организован тепловой контур, обеспечивающий температуру внутри \r\nпомещений не ниже 10ºС и влажность воздуха не более 60%.", "[стр. 41]\n3494.2-ПОС 41 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n13. ОБОСНОВАНИЕ ПОТРЕБНОСТИ СТРОИТЕЛЬСТВА В КАДРАХ,\r\nОСНОВНЫХ СТРОИТЕЛЬНЫХ МАШИНАХ, МЕХАНИЗМОВ, \r\nТРАНСПОРТНЫХ СРЕДСТВАХ, В ТОПЛИВЕ И ГОРЮЧЕ￾СМАЗОЧНЫХ МАТЕРИАЛАХ, А ТАКЖЕ В ЭЛЕКТРИЧЕСКОЙ \r\nЭНЕРГИИ, ВОДЕ, ВРЕМЕННЫХ ЗДАНИЯХ И СООРУЖЕНИЯХ \r\n13.1 ПОТРЕБНОСТЬ РАБОЧИХ КАДРОВ ПРИ СТРОИТЕЛЬСТВЕ\r\nПотребность строительства в рабочих кадрах удовлетворяется за счет \r\nналичия кадров у генерального подрядчика и субподрядных организаций. \r\nЖильем и бытовым обслуживанием строительные кадры обеспечиваются за \r\nсчет имеющегося фонда у строительных и субподрядных организаций. \r\nРаботы ведутся в 3 смены по 8 часов. \r\nНеобходимое потребное количество строительных кадров строительст￾ва, с учетом персонала занятого в прочих хозяйствах, определяется по \r\nформуле: \r\nW T\r\nS\r\nR\r\n⋅\r\n= , где (1) \r\nR-количество работающих на площадке, чел.; \r\nS-стоимость строительных, монтажных и временных зданий и сооруже￾ний на расчетный период, тыс.руб.; \r\nW-среднегодовая выработка на одного работающего, тыс.руб./чел/год; \r\nT-продолжительность выполнения работ, годы \r\nСметная стоимость СМР в максимально-напряженный год (5 год строи￾тельства) составляет 4106220,0 тыс. руб в ценах 1 квартала 2012 года. \r\nДля выполнения расчетов проектом принимается среднегодовая выра￾ботка на одного работающего равная 19850 тыс.руб./чел./год. \r\nТак как основные работы- земляные и в основном механизированные, \r\nколичество людей по формуле 1 считать нецелесообразно. Количество лю￾дей берется по проектам аналогам и по опыту строительства данных соору￾жений. Потребность строительства в рабочих представлена в таблице 2.", "[стр. 42]\n3494.2-ПОС 42 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nТаблица 2 \r\nВ том числе: \r\nГод строи￾тельства, \r\nкв-лы \r\nСтоимость \r\nСМР, \r\nтыс. руб. \r\nГодовая \r\nвыработка \r\nна 1 рабо￾тающего, \r\nтыс. руб. \r\nОбщая чис￾ленность \r\nработающих Рабочие ИТР Служа￾щие \r\nМОП и \r\nохрана \r\n1 год \r\n(IV кв. 2012 511 112 19 850 103 87 11 4 1 \r\n2 год (2013) 1 245 575 19 850 63 53 7 2 1 \r\n3 год (2014) 3 563 591,3 19 850 315 264 35 11 5 \r\n4 год (2015) 3 800 458,6 19 850 337 282 37 12 6 \r\n5 год (2016) 4 106 220,0 19 850 364 305 40 13 6 \r\n6 год (2017) 1 596 352,2 19 850 141 117 15 5 3 \r\n7 год (2018) 1 326 314,87 19850 66 55 7 2 2 \r\n13.2 ОБОСНОВАНИЕ ПОТРЕБНОСТИ СТРОИТЕЛЬСТВА В ОСНОВНЫХ \r\nСТРОИТЕЛЬНЫХ МАШИНАХ, МЕХАНИЗМОВ, ТРАНСПОРТНЫХ СРЕДСТВАХ \r\nРасчет потребности в основных машинах и механизмах произведен из ус￾ловия объемов работ по отдельным работам в максимально напряженный год. \r\nПотребности в основных машин, механизмах, оборудовании и приспособ￾лениях для максимально напряжённого года строительства приведены в таб￾лице 3. \r\nТаблица 3 \r\nНаименование машин Ед.изм. \r\nКоличество \r\nЭкскаватор шт. 6 \r\nБульдозер шт. 6 \r\nАвтогрейдеры шт. 2 \r\nПогрузчики одноковшовые шт. 3 \r\nКраны стреловые шт. 2 \r\nТрубоукладчики шт. 4 \r\nТрактор шт. 4 \r\nКаток шт. 4 \r\nТрамбовочные машины шт. 2 \r\nТрансформаторные подстанции шт. 2 \r\nЭлектростанции передвижные шт. 2", "[стр. 43]\n3494.2-ПОС 43 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПотребность в автотранспорте представлена в таблице 4. \r\nТаблица 4 \r\n13.3 ОБОСНОВАНИЕ ПОТРЕБНОСТИ СТРОИТЕЛЬСТВА В ТОПЛИВЕ И ГОРЮЧЕ￾СМАЗОЧНЫХ МАТЕРИАЛАХ, А ТАКЖЕ В ЭЛЕКТРИЧЕСКОЙ ЭНЕРГИИ, В СЖАТОМ \r\nВОЗДУХЕ, ВОДЕ\r\n13.3.1 Обоснование потребности в топливе, ГСМ \r\nПотребность в топливе определяется по “Расчетным нормативам для \r\nсоставления проектов организации строительства” часть 1 2-е издание, до￾полненное ЦНИИОМТП, Москва, 1973 г.\r\nКоэффициент, учитывающий изменение сметной стоимости строитель￾ства в зависимости от района строительства принимается 1,58. \r\n Pп=К1*P (2) \r\nОбоснование потребности в топливе представлена в таблице 5. \r\nТаблица 5 \r\nГод строительства, \r\nмесяцы \r\nСтоимость СМР, \r\nтыс. руб. \r\n(в ценах 2012 г) \r\nСтоимость СМР,\r\nтыс. руб. \r\n(в ценах 1969 г). \r\nНорматив￾ный \r\nпоказатель \r\nКоличество, \r\nт \r\n1 год \r\n(IV кв. 2012 511 112 2,27 68 107,4 \r\n2 год (2013) 1 245 575 5,54 58 91,6 \r\n3 год (2014) 3 563 591,3 15,84 44 69,5 \r\n4 год (2015) 3 800 458,6 16,90 44 69,5 \r\n5 год (2016) 4 106 220,0 18,2 44 69,5 \r\n6 год (2017) 1 596 352,2 7,09 51 80,5 \r\n7 год (2018) 1 326 314,87 5,89 58 91,6 \r\nНаименование автотранспорта Ед.изм. \r\nКоличество \r\nАвтотранспорт самосвальный шт 24 \r\nАвтотранспорт бортовой \r\n― прицепы шт 3 \r\nСпециализированный транспорт шт 2", "[стр. 44]\n3494.2-ПОС 44 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n13.3.2 Расчет искусственного освещения строительной площадки \r\nИскусственное освещение рабочих мест, проходов и проездов на \r\nстроительстве в тёмное время суток произведено в соответствии с ГОСТ \r\n12.1.046-85 \r\nДля освещения площадок и дорог, находящихся вблизи строящегося \r\nздания и сооружений, рекомендуется установка прожекторов на мачтах из \r\nметаллических труб диаметром 150 мм. \r\nДля освещения рабочих мест рекомендуется использовать лёгкие пе￾реносные светильники и переносные прожекторные вышки. \r\nПотребное количество прожекторов для освещения территории строи￾тельства рассчитывается по следующей формуле: \r\nП=Р х S/ Рп , где \r\nП – потребное количество прожекторов, шт. \r\nР – удельная мощность в Вт/м² \r\nS – площадь освещаемой территории, м² \r\nРп – мощность ламы, устанавливаемой в прожекторе, (принимается \r\n1000 Вт). \r\nР=0,14 х Е х К, где (3) \r\nЕ – минимальная горизонтальная освещённость в лк (для расчёта Е=10 \r\nлк) \r\nК – коэффициент запаса (для расчёта принят 1,3). \r\n0,14 – статический коэффициент. \r\nР=0,14 х 10 х 1,3=1,82 Вт/м² \r\nДля насосной станции оборотной воды: \r\nП=1,82 х 4800/ 1000=9 шт.- принимаем 9 шт. \r\nДля узла переключения трубопроводов №1 \r\nП=1,82 х 5000/ 1000=9шт.- принимаем 9 шт \r\nДля узла переключения трубопроводов №1 \r\nП=1,82 х 6000/ 1000=11 шт.- принимаем 12 шт \r\nДля освещения площадки строительства насосной станции оборотной \r\nводы приняты прожекторы типа ПЗС-200, мощностью 700 Вт с подключени￾ем путём прокладки временной воздушной линии на временных опорах из \r\nметаллических труб диаметром 150 мм. \r\nНа территории строительной площадки потребуется установить : \r\n• насосная станция оборотной воды 4 шт. мачт.; \r\n• узел переключения трубопроводов 4 шт. мачт; \r\n• узел переключения трубопроводов 4 шт. мачт.", "[стр. 45]\n3494.2-ПОС 45 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nДля остальных сооружений (для линейных) расстановка мачт через 50-\r\n75 метров, угол наклона 60 град. к горизонту (3 прожектора на мачте). \r\n13.3.3 Обоснование потребности в электроэнергии \r\nПотребность в электроэнергии определяется по “Расчетным нормати￾вам для составления проектов организации строительства” часть 1 2-е из￾дание, дополненное ЦНИИОМТП, Москва, 1973 г.\r\nКоэффициент, учитывающий изменение сметной стоимости строитель￾ства в зависимости от района строительства принимается 1,58. \r\nОбоснование потребности в электроэнергии представлена в таблице 6. \r\nТаблица 6 \r\nГод строительства, \r\nмесяцы \r\nСтоимость СМР, \r\nтыс. руб. \r\n(в ценах 2012 г) \r\nСтоимость СМР,\r\nтыс. руб. \r\n(в ценах 1969 г). \r\nНорматив￾ный \r\nпоказатель \r\nКоличество, \r\nкВа \r\n1 год \r\n(IV кв. 2012 511 112 2,27 170 268,6 \r\n2 год (2013) 1 245 575 5,54 145 229,1 \r\n3 год (2014) 3 563 591,3 15,84 120 186,9 \r\n4 год (2015) 3 800 458,6 16,90 113 184,9 \r\n5 год (2016) 4 106 220,0 18,2 115 181,7 \r\n6 год (2017) 1 596 352,2 7,09 145 229,1 \r\n7 год (2018) 1 326 314,87 5,89 145 229,1 \r\n13.3.4 Обоснование потребности в паре \r\nПотребность в паре определяется по “Расчетным нормативам для со￾ставления проектов организации строительства” часть 1 2-е издание, до￾полненное ЦНИИОМТП, Москва, 1973 г.\r\nКоэффициент, учитывающий изменение сметной стоимости строитель￾ства в зависимости от района строительства принимается 1,58. \r\nОбоснование потребности в паре представлена в таблице 7. \r\nТаблица 7 \r\nГод строительства, \r\nмесяцы \r\nСтоимость СМР, \r\nтыс. руб. \r\n(в ценах 2012 г) \r\nСтоимость СМР,\r\nтыс. руб. (в ценах \r\n1969 г). \r\nНорматив￾ный \r\nпоказатель \r\nКоличество, \r\nкг/ч \r\n1 год \r\n(IV кв. 2012 511 112 2,27 162 258 \r\n2 год (2013) 1 245 575 5,54 138 218 \r\n3 год (2014) 3 563 591,3 15,84 94 148,5 \r\n4 год (2015) 3 800 458,6 16,90 90 142,2 \r\n5 год (2016) 4 106 220,0 18,2 88 139 \r\n6 год (2017) 1 596 352,2 7,09 115 181,7 \r\n7 год (2018) 1 326 314,87 5,89 138 218", "[стр. 46]\n3494.2-ПОС 46 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n13.3.5 Обоснование потребности в сжатом воздухе \r\nПотребность в сжатом воздухе, 3\r\nм /мин, определяется по формуле: \r\nQ 4,1 q K0 = ∑⋅ ⋅ , (4) \r\nгде ∑q – общая потребность в воздухе пневмоинструмента; \r\nKО\r\n – коэффициент при одновременном подключении пневмоинстру￾мента. \r\n3 Q = 4,1 ⋅13⋅ 9,0 =16м /мин \r\nПринимаем 2 компрессора ДК-8 (производительность 8 3 м /мин) \r\n13.3.5 Обоснование потребности в воде \r\nПотребность QТР в воде определяется суммой расхода на производст￾венные QПР и хозяйственно-бытовые QХОЗ нужды: \r\nQТР = QПР +QХОЗ (5) \r\nРасход воды на производственные потребности, л/с: \r\nt\r\nq П K\r\nQ K\r\nП П Ч\r\nПР H\r\n⋅\r\n⋅\r\n=\r\n3600\r\n, где (6) \r\nqП = 500л – расход воды на производственного потребителя (поливка \r\nбетона, заправка и мытье машин и т.д.); \r\nПП – число производственных потребителей в наиболее загруженную \r\nсмену; \r\nKЧ = 5,1 – коэффициент часовой неравномерности водопотребления; \r\nt = 8ч – число часов в смене; \r\nK Н = 2,1 – коэффициент на неучтенный расход воды. \r\nДля первой и второй очереди: \r\nQ л с ПР ,0125 /\r\n3600 8\r\n500 4 5,1\r\n2,1 =\r\n⋅\r\n⋅ ⋅\r\n= \r\nРасход воды на хозяйственно-бытовые потребности, л/с: \r\n3600 60 1\r\nt\r\nq П\r\nt\r\nq П K\r\nQ K\r\nП Р Ч Д Д\r\nХОЗ H\r\n⋅\r\n⋅\r\n+\r\n⋅\r\n⋅\r\n= , (7) \r\nгде q X = 15л – удельный расход воды на хозяйственно-питьевые по￾требности работающего; \r\nПР\r\n – численность работающих в наиболее загруженную смену;", "[стр. 47]\n3494.2-ПОС 47 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nKЧ = 2– коэффициент часовой неравномерности потребления воды; \r\nq Д = 30л – расход воды на прием душа одним работающим; \r\nП Д\r\n – численность пользующихся душем (до 80% ПР ); \r\nt\r\n1 = 45мин – продолжительность использования душевой установки; \r\nt = 8ч – число часов в смене; \r\nДля первой очереди: \r\n7.9\r\n60 45\r\n30 8,0 98\r\n3600 8\r\n15 98 2\r\nQХОЗ =\r\n⋅\r\n⋅ ⋅\r\n+\r\n⋅\r\n⋅ ⋅\r\n= л/сек. \r\nQтр. = 0,125+ 9,7 = 1,095 л/сек. \r\n13.4 ОБОСНОВАНИЕ ПОТРЕБНОСТИ СТРОИТЕЛЬСТВА ВО ВРЕМЕННЫХ ЗДАНИЯХ \r\nИ СООРУЖЕНИЯХ\r\nПотребность строительства во временных зданиях и сооружениях оп￾ределяется для всего срока строительства занятых при строительстве. \r\nУдельный вес категории работающих на строительной площадке со￾ставляет: \r\n— Рабочие − 364 × 83,9% = 305 чел. \r\n— ИТР − 364 × 11 % = 40 чел. \r\n— Служащие − 364 × З,6% = 13 чел. \r\n— МОП и охрана − 364× 1,5% = 6 чел. \r\nДля расчета площадей зданий санитарно-бытового назначения, учиты￾вается, что в наиболее многочисленную смену число работающих составля￾ет 70% от общего количества, а ИТР и служащих составляет 80%: \r\nРабочие: 102 × 70% = 71 чел. \r\nИТР: 17 × 80% = 13 чел. \r\nПотребность во временных инвентарных зданиях определяется путем \r\nпрямого счета. \r\nДля инвентарных зданий санитарно-бытового назначения: \r\nSтр = NSп, (8) \r\nгде Sтр - требуемая площадь, м2\r\n; \r\nN - общая численность работающих (рабочих) или численность рабо￾тающих (рабочих) в наиболее многочисленную смену, чел.; \r\nSп - нормативный показатель площади, м2\r\n/чел. \r\nГардеробная \r\nSтр = N0,7 м2\r\n,", "[стр. 48]\n3494.2-ПОС 48 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nгде N - общая численность рабочих (в двух сменах). \r\nSтр =196*0,7=137 м2 \r\nДушевая: \r\nSтр = N0,54 м2\r\n, \r\nгде N - численность рабочих в наиболее многочисленную смену, \r\nпользующихся душевой (80 %). \r\nSтр =98*0,54=53 м2 \r\nУмывальная: \r\nSтр = N0,2 м2\r\n, \r\nгде N - численность работающих в наиболее многочисленную смену. \r\nSтр =98*0,2=19,6 м2 \r\nПомещение для сушки одежды : \r\nSтр = N0,2 м2\r\n, \r\nгде N - численность рабочих в наиболее многочисленную смену. \r\nSтр =98*0,2=19,6 м2 \r\nПомещение для обогрева рабочих: \r\nSтр = N0,1 м2\r\n, \r\nгде N - численность рабочих в наиболее многочисленную смену. \r\nSтр =98*0,1=9,8 м2 \r\nТуалет: \r\nSтр = (0,7 N0,1)·0,7 + (1,4 N0,1)·0,3, \r\nгде N - численность рабочих в наиболее многочисленную смену; \r\n0,7 и 1,4- нормативные показатели площади для мужчин и женщин \r\nсоответственно; \r\n0,7 и 0,3 - коэффициенты, учитывающие соотношение, для мужчин и \r\nженщин соответственно. \r\nSтр = (0,7 *98*0,1)·0,7 + (1,4 *98*0,1)·0,3 = 8,9 м2\r\n, \r\nДля инвентарных зданий административного назначения: \r\nSтр = NSн\r\nгде Sтр - требуемая площадь, м2\r\n; \r\nSн = 4 - нормативный показатель площади, м2\r\n/чел.; \r\nN - общая численность ИТР, служащих, МОП и охраны в наиболее \r\nмногочисленную смену. \r\nSтр =6*4=24м2", "[стр. 49]\n3494.2-ПОС 49 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПлощади временных инвентарных зданий и сооружений представлены в \r\nтаблице 8. \r\nТаблица 8 \r\nНаименование \r\nНорма на \r\n1 работающего \r\nв м2\r\nКоличество чело￾век, работающих \r\nв смену \r\nОбщая \r\nпотребность в \r\nм\r\n2\r\nЧисло ин￾вентарных \r\nзданий \r\n1. Контора 4 13 52 3 \r\n2. Диспетчерская 7 4 28 2 \r\n3. Гардеробная 0,7 196 137 8 \r\n4 Умывальная 0,2 98 19,6 2 \r\n5. Душевая 0,54 98 53 4 \r\n6.Помещение для сушки \r\nодежды \r\n0,2 98 19,6 2 \r\n7. Помещения для обог￾ревания рабочих 0,1 98 9,8 1 \r\n8. Туалет (кабинка) 98 9 9 \r\n9. Навес для отдыха и \r\nместо для курения \r\n0,4 98 40 \r\nИтого: м2\r\n 386 33 \r\nКомплект средств для \r\nпожаротушения (щит, ин￾струмент, огнетушители, \r\nбочка с водой и ящик \r\nс песком) \r\n1/2000 \r\nкомплект/м2\r\n(площади \r\nгородка), \r\nно не менее \r\nодного \r\n98 2 \r\nМусоросборник 1/(50…100) 98 4 \r\nВ качестве инвентарных зданий применяются здания контейнерного \r\nтипа системы «УНИВЕРСАЛ» с габаритными размерами \r\nДхШхВ=6,0х3,0х2,835м.", "[стр. 50]\n3494.2-ПОС 50 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n14. ОБОСНОВАНИЕ РАЗМЕРОВ И ОСНАЩЕНИЯ ПЛОЩАДОК ДЛЯ \r\nСКЛАДИРОВАНИЯ МАТЕРИАЛОВ, КОНСТРУКЦИЙ, \r\nОБОРУДОВАНИЯ, УКРУПНЕННЫХ МОДУЛЕЙ И СТЕНДОВ ДЛЯ ИХ \r\nСБОРКИ. РЕШЕНИЯ ПО ПЕРЕМЕЩЕНИЮ ТЯЖЕЛОВЕСНОГО \r\nНЕГАБАРИТНОГО ОБОРУДОВАНИЯ, УКРУПНЕННЫХ МОДУЛЕЙ И \r\nСТРОИТЕЛЬНЫХ КОНСТРУКЦИЙ \r\nДанные о запасах основных материалов и изделий на складах строи￾тельства (в днях) представлены в таблице 9. \r\nТаблица 9 \r\nМатериалы и изделия При перевозке автотранспортом на \r\nрасстоянии более 50 км \r\nТрубы стальные, электротехнические материалы. 15-20 \r\nМеталлоконструкции 10-15 \r\nЩебень , песок 7-20 \r\nПлощадь складов для хранения материалов, изделий и оборудования в \r\nмаксимально-напряженный год приведена ниже в таблице 10. \r\nТаблица 10 \r\nМатериалы и изделия Всего \r\nм\r\n2\r\nI Закрытые склады \r\nотапливаемые \r\n120 \r\nнеотапливаемые 30 \r\nII Навесы 200 \r\nIII Склады огнеопасных материалов: 40 \r\nIV Открытые складские площадки 300 \r\nИтого: 690 \r\nПодъемно-транспортное и производственно-технологическое \r\n(навес) 90 \r\nПротивопожарное оборудование, строительный инвентарь, тара \r\nметаллическая (закрытый неотапливаемый) 60 \r\nИтого: 150 \r\nВсего: 840", "[стр. 51]\n3494.2-ПОС 51 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n15. ПРЕДЛОЖЕНИЯ ПО ОБЕСПЕЧЕНИЮ КОНТРОЛЯ КАЧЕСТВА \r\nСТРОИТЕЛЬНЫХ И МОНТИРУЕМЫХ ОБОРУДОВАНИЯ, \r\nКОНСТРУКЦИЙ И МАТЕРИАЛОВ \r\nГеотехнический контроль качества укладываемых грунтов\r\nПри геотехническом контроле качества укладываемых грунтов необхо￾димо руководствоваться РД 34 15.073-91 «Руководство по геотехническому \r\nконтролю за подготовкой оснований и возведением грунтовых сооружений в \r\nэнергетическом строительстве». \r\nКонтроль качества оснований и грунтовых сооружений должен вестись \r\nдля: \r\nа) проверки обеспечения значений физико-механических характеристик \r\nгрунтов, принятых в расчетах при проектировании этих сооружений с учетом \r\nконструкций и технологий их возведения; \r\nб) накопления и анализа данных о физико-механических характеристи￾ках грунтов с целью выявления закономерностей их изменений, возникаю￾щих в процессе укладки, а также в случае необходимости внесения коррек￾тировки в ТУ на возведение земляных сооружений и оснований; \r\nв) оценки принятой технологии возведения сооружений из грунтовых \r\nматериалов; \r\nг) оценки физико-механических характеристик грунтов в период их ук￾ладки в тело сооружения, а также изменения их во времени при вводе со￾оружения в эксплуатацию и в период его эксплуатации. \r\nКонтроль качества грунта основания и грунта, уложенного в земляное \r\nсооружение, соответствие его требованиям проекта, техническим условиям, \r\nстроительным нормам и правилам, а также соответствие технологии возве￾дения сооружения проекту организации производства работ, строительным \r\nнормам и правилам осуществляется геотехнической службой строительст￾ва. \r\nПри производстве работ необходимо осуществлять контроль качества. \r\nВ зависимости от места и времени проведения контроля в технологиче￾ском процессе: \r\n— входной контроль - контроль поступающих материалов, изделий, \r\nконструкций, грунта и т.п., а также технической документации. Кон￾троль осуществляется преимущественно регистрационным методом", "[стр. 52]\n3494.2-ПОС 52 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n(по сертификатам, накладным, паспортам и т.п.), а при необходимо￾сти - измерительным методом; \r\n— операционный контроль - контроль, выполняемый в процессе про￾изводства работ или непосредственно после их завершения. Осу￾ществляется преимущественно измерительным методом или техни￾ческим осмотром. Результаты операционного контроля фиксируют￾ся в общих или специальных журналах работ, журналах геотехниче￾ского контроля и других документах, предусмотренных действующей \r\nв данной организации системой управления качеством;\r\n— приемочный контроль - контроль, выполняемый по завершении \r\nстроительства объекта или его этапов, скрытых работ или других \r\nобъектов контроля. По его результатам принимается документиро￾ванное решение о пригодности объекта контроля к эксплуатации \r\nили выполнению последующих работ. \r\nРезультаты приемочного контроля фиксируются в актах освидетельст￾вования скрытых работ, актах промежуточной приемки ответственных кон￾струкций, актах испытания свай пробной нагрузкой и других документах, \r\nпредусмотренных действующими нормативами по приемке строительных \r\nработ, зданий и сооружений. \r\nВ зависимости от применения специальных средств контроля (метод \r\nконтроля): \r\n— измерительный контроль, выполняемый с применением средств из￾мерений, в т.ч. лабораторного оборудования; \r\n— визуальный контроль - по ГОСТ 16504-81; \r\n— технический осмотр - по ГОСТ 16504-81; \r\n— регистрационный контроль, выполняемый путем анализа данных, \r\nзафиксированных в документах (сертификатах, актах освидетельст￾вования скрытых работ, общих или специальных журналах работ и \r\nт.п.). Применяется при недоступности объекта контроля или неце￾лесообразности выполнения измерительного или визуального кон￾троля (например, определение вида грунта для насыпи при наличии \r\nматериалов инженерно-геологических изысканий по карьеру). \r\nСлужба геотехнического контроля организуется строительной органи￾зацией к началу земляных работ и действует на протяжении всего периода \r\nстроительства до полного окончания работ. \r\nГеотехнический контроль качества грунта в основании и грунта, уложенно￾го в земляное сооружение, осуществляется путем визуальных наблюдений за", "[стр. 53]\n3494.2-ПОС 53 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nстроительством, отбора проб грунта из основания или из сооружения и иссле￾дования физических, механических и химических характеристик этого грунта и \r\nгрунтовой воды в соответствии с действующими государственными стандарта￾ми, отраслевыми стандартами, стандартами предприятий, техническими усло￾виями и инструкциями по определению свойств и характеристик грунтов. \r\nРезультаты геотехнического контроля качества возведения земляного \r\nсооружения заносят в журналы и ведомости, суточные рапорты и изобра￾жают в виде графиков. Эти материалы составляют отчетную техническую \r\nдокументацию геотехнической службы. \r\nКроме операционного геотехнического контроля, осуществляемого гео￾технической службой, необходимо с помощью приемочной комиссии произ￾водить освидетельствование скрытых работ и промежуточную приемку за￾конченных конструктивных элементов и частей земляного сооружения. \r\nМатериалы, полученные при геотехническом контроле, служат для оцен￾ки качества основания и возведенного сооружения, его соответствия проекту. \r\nЕсли в процессе эксплуатации дамб будут обнаружены явления, не отвечаю￾щие установленным требованиям, результаты геотехнического контроля \r\nдолжны использоваться для оценки степени опасности этих явлений и для \r\nразработки мероприятий, обеспечивающих надежность и долговечность со￾оружения. \r\nВ случаи возведения грунтового сооружения в зимний период геотехни￾ческий контроль за его возведением должен осуществляться по техниче￾ским условиям, учитывающим температурно-влажностный режим места \r\nстроительства. \r\nВ зимний период геотехническая лаборатория помимо гранулометриче￾ского состава и плотности сухого грунта, укладываемого в сооружение, ве￾дет наблюдения за состоянием грунта в процессе работ, за температурой \r\nвоздуха, скоростью ветра, атмосферными осадками, температурой грунта, \r\nукладываемого в основание и сооружение как в процессе работ, так и после \r\nих окончания, за содержанием мерзлых комьев в слое, за толщиной слоя \r\nпромороженного грунта. \r\nУкладка грунта в насыпи гидротехнических сооружений разрешается \r\nтолько после подготовки основания в соответствии с проектом и принятия \r\nего комиссией по акту.\r\nПодготовка основания производится в соответствии с проектом и до￾полнительными требованиями, которые могут возникнуть после вскрытия \r\nоснования.", "[стр. 54]\n3494.2-ПОС 54 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n16. ПРЕДЛОЖЕНИЯ ПО ОРГАНИЗАЦИИ СЛУЖБЫ \r\nГЕОДЕЗИЧЕСКОГО И ЛАБОРАТОНОГО КОНТРОЛЯ \r\nГеодезическая подготовка строительной площадки производится в сле￾дующем порядке: \r\n― создание планового геодезического обоснования строительной сет￾ки, позволяющего при рабочем проектировании обеспечить геоде￾зические разбивочные работы в процессе строительства (вынос и \r\nзакрепление осей проектируемых зданий и сооружений, геодезиче￾ский контроль точности выполнения строительно-монтажных работ); \r\n― создание высотного геодезического обоснования, позволяющего \r\nпри рабочем проектировании обеспечить геодезические работы в \r\nпроцессе строительства, высотную разбивку положения конструкций \r\nзданий, геодезический контроль точности выполнения строительно￾монтажных работ. \r\nРаботы по построению на местности строительной сетки следует вы￾полнять по проекту или схеме, составляемым в соответствии с генеральным \r\nпланом объекта строительства. В проекте или схеме указываются координа￾ты и отметки, а в пояснительной записке указывается точность построения \r\nгеодезической основы. \r\nГеодезическая разбивочная основа для строительства создается со￾гласно СНиП 3.01.03-84 «Геодезические работы в строительстве» и СНиП \r\n11-02-96 «Инженерные изыскания для строительства. Основные положе￾ния». Заказчик обязан создать геодезическую разбивочную основу для \r\nстроительства и не менее чем за 10 дней до начала строительно￾монтажных работ передать подрядчику техдокументацию по геодезической \r\nразбивочной основе и закрепленным на строительной площадке пунктам и \r\nзнакам этой основы, в том числе: \r\n― пункты строительной сетки, красные линии; \r\n― оси, определяющие положение и габариты зданий и сооружений в \r\nплане, закрепленные створными знаками в количестве не менее че￾тырех на каждую ось, а также оси транспортных и инженерных внут-\r\n.риплощадочных коммуникаций, закрепленных знаками на прямых \r\nучастках не менее чем через 0,5 км и на углах поворота; \r\n― реперы по границам и внутри застраиваемой территории, в количе￾стве не менее двух у каждого отдельно размещаемого здания и со￾оружения, а также реперы вдоль осей транспортных и инженерных", "[стр. 55]\n3494.2-ПОС 55 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nкоммуникаций не реже чем через 0,5 км ( СНиП 3.01.03-84 «Геоде￾зические работы в строительстве», пп.2.13.). \r\nПункты геодезической основы должны быть закреплены постоянными и \r\nвременными знаками. \r\nВо время строительства необходимо вести наблюдения за устойчиво￾стью знаков плановой основы до 2-х раз в год и выносной основы до 4-х раз \r\nв год. \r\nКонтроль за сохранностью и устойчивостью знаков геодезической раз￾бивочной основы осуществляет подрядная строительная организация. \r\nОтветственные конструкции, подлежащие промежуточной приемке с \r\nсоставлением геодезической съемки: \r\n― отметки фундаментных плит, плит перекрытий и покрытий; \r\n― основные параметры металлических и железобетонных каркасов \r\nзданий; \r\n― параметры опорных элементов перед установкой технологического \r\nоборудования. \r\nТочность разбивочных работ и контроля качества в процессе строи￾тельства следует принимать, руководствуясь данными, приведенными в \r\nтаблице 11. \r\nТаблица 11 \r\nВеличины средних квадратических погрешностей построения внешней и внутренней \r\nразбивочных сетей здания (сооружения) и других разбивочных работ \r\nЛинейные \r\nизмерения \r\nУгловые \r\nизмерения \r\nс \r\nОпределение \r\nпревышения на \r\nстанции, мм \r\nОпределение от￾метки на монтажном \r\nгоризонте относи￾тельно исходного, \r\nмм \r\nПередача точек, \r\nосей \r\nпо вертикали, \r\nмм \r\n10000\r\n1\r\n10 2 \r\nЧисловые значения погрешностей \r\nследует назначать в зависимости \r\nот высоты монтажного горизонта \r\n(согласно обязательным прило￾жениям 4 и 5 СНиП 3.01.03-84) \r\n17. ПЕРЕЧЕНЬ ТРЕБОВАНИЙ, КОТОРЫЕ ДОЛЖНЫ БЫТЬ УЧТЕНЫ\r\nВ РАБОЧЕЙ СТАДИИ ДОКУМЕНТАЦИИ \r\nДанный раздел не предусматривает мероприятий, которые необходимо \r\nучесть при разработке рабочей документации.", "[стр. 56]\n3494.2-ПОС 56 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n18. ОБОСНОВАНИЕ ПОТРЕБНОСТИ В ЖИЛЬЕ И СОЦИАЛЬНО￾БЫТОВОМ ОБСЛУЖИВАНИИ ПЕРСОНАЛА, УЧАСТВУЮЩЕГО В \r\nСТРОИТЕЛЬСТВЕ \r\nПотребность строительства в рабочих кадрах удовлетворяется за счет \r\nналичия кадров у генерального подрядчика и субподрядных организаций. \r\nПотребность в жилье и социально-бытовом обслуживании персонала не \r\nтребуется. \r\n19. ПЕРЕЧЕНЬ МЕРОПРИЯТИЙ И ПРОЕКТНЫХ РЕШЕНИЙ ПО \r\nОПРЕДЕЛЕНИЮ ТЕХНИЧЕСКИХ СРЕДСТВ И МЕТОДОВ РАБОТЫ, \r\nОБЕСПЕЧИВАЮЩИХ ВЫПОЛНЕНИЕ НОРМАТИВНЫХ \r\nТРЕБОВАНИЙ ОХРАНЫ ТРУДА \r\nПри производстве строительно-монтажных работ строго соблюдать \r\nтребования безопасности труда в соответствии с СНиП 12-03-2001 «Безо￾пасность труда в строительстве. Часть 1. Общие требования», СНиП 12-04-\r\n2002 «Безопасность труда в строительстве. Часть 2. Строительное произ￾водство», ПОТ РМ 012-2000 «Межотраслевыми правилами по охране труда \r\nпри работе на высоте», ППБ-01-03 «Правилами пожарной безопасности в \r\nРФ» , ПБ 10-382-00 «Правилами устройства и безопасной эксплуатации гру￾зоподъемных кранов, СП 12-136-2002 «Решения по охране труда и про￾мышленной безопасности в проектах организации строительства и проектах \r\nпроизводства работ», СанПиН 2.2.3.1384-03 «Гигиеническими требованиями \r\nк организации строительного производства и строительных работ» и други￾ми нормативными документами по охране труда, перечисленными в прило￾жении А к СНиП 12-03-2001. \r\nСостав и содержание решений по безопасности труда определен в со￾ответствии с приложением К , СНиП 12.03-2001. \r\nОсновными опасными производственными факторами при производст￾ве работ являются: \r\n• работа строительных машин и механизмов; \r\n• работа на высоте; \r\n• работа с электроинструментом и вблизи электрических сетей; \r\n• работы по транспортированию и складированию строительных \r\nгрузов;", "[стр. 57]\n3494.2-ПОС 57 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n• опасность возникновения пожара; \r\n• вредные санитарно-гигиенические факторы (недостаточная ос￾вещенность, химически активные или ядовитые вещества). \r\nПеред началом выполнения строительно-монтажных работ на террито￾рии стройплощадки необходимо оформить акт-допуск по форме приложения \r\nВ СНиП 12-03-2001. \r\nПриказами по организации должны быть назначены лица, ответствен￾ные за обеспечение охраны труда в пределах порученных им участков ра￾бот в соответствии с п. 5.5 СНиП 12-03-2001, а также лицо, ответственное за \r\nбезопасное производство работ краном, в соответствии с ПБ 10-382-00. \r\nВ организации и на строительной площадке должно быть организовано \r\nпроведение проверок, контроля и оценки состояния охраны и условий безо￾пасности труда на различных уровнях и по формам в соответствии с п. 5.9 \r\nСНиП 12-03-2001. \r\nОкончание подготовительных работ на строительной площадке должно \r\nбыть принято по акту о выполнении мероприятий по безопасности труда, \r\nоформленного согласно приложению И СНиП 12-03-2001.\r\nТерритория строительной площадки огораживается постоянным ограж￾дением, а участки производства работ - временными ограждениями по \r\nГОСТ 12.4.059-89 ССБТ. \r\nВо время производства работ на строительной площадке исключается \r\nприсутствие посторонних лиц. Строительная площадка оборудуется необ￾ходимыми знаками безопасности и наглядной агитацией. \r\nПогрузку грунта на автосамосвалы осуществлять со стороны заднего \r\nили бокового борта. Пронос экскаваторного ковша над кабиной автомобиля \r\nзапрещается. При погрузке автосамосвала его водитель должен быть вне \r\nопасной зоны. Нагруженный автосамосвал может начинать движение только \r\nпосле разрешающего сигнала машиниста экскаватора. \r\nВо время работы экскаватора нельзя находиться посторонним в радиу￾се его действия плюс 5 м. Перед началом работы или движения машины \r\nнеобходимо подавать звуковой или световой сигнал. Оставлять без надзора \r\nмашины с работающим двигателем запрещается. \r\nРаботы на высоте ближе 2 м от не огражденных перепадов по высоте \r\nболее 1,3 м ведут с применением предохранительного пояса. При этом \r\nоформляется наряд-допуск на производство работ повышенной опасности \r\nсогласно Приложения \"Д\" к СНиП 12-03-2001.", "[стр. 58]\n3494.2-ПОС 58 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nДо начала работ прораб должен ознакомить всех рабочих с наиболее \r\nопасными моментами работ и обязан принять все меры предосторожности \r\nдля предупреждения несчастных случаев. \r\nПри работах на высоте запрещается выполнение работ при ветре си￾лой 6 баллов (скорость 12 м/сек) и более, а также при дожде и грозе. \r\nПри работе кранов необходимо соблюдать требования СНиП 12-03-\r\n2001, прежде всего разделов 7.1, 7.2, 8.1, 8.2, касающихся требований к экс￾плуатации кранов и безопасности выполнения погрузочно-разгрузочных ра￾бот, а также требования СНиП 12-04-2002 и ПБ 10-382-00. Во избежание \r\nдоступа посторонних лиц опасные зоны работы крана должны быть ограж￾дены сигнальным ограждением. \r\nПри подаче бетонной смеси к месту укладки при помощи автобетонона￾соса следует соблюдать следующие правила: \r\n• до начала работы испытать бетоновод при гидравлическом дав￾лении, в 1,5 раза превышающем рабочее; \r\n• место укладки бетонной смеси связать сигнализацией с местом \r\nустановки бетононасоса; \r\n• вокруг бетононасоса оставить проходы шириной не менее 1 м; \r\n• замковые соединения бетоновода перед подачей бетонной смеси \r\nочистить и плотно закрыть; \r\n• проталкивание бетонной смеси в горловине приемного бункера \r\nбетононасоса и снятие звеньев бетоновода производить только \r\nпосле полной остановки бетононасоса. \r\nПри уплотнении бетонной смеси запрещается подтаскивать вибратор \r\nза кабель. \r\nПри обслуживании автобетононасоса приемный бункер, электродвига￾тели, механическое оборудование, электрокабели должны быть закрыты \r\nспециальными щитками. \r\nСтроительная площадка должна быть оборудована комплексом пер￾вичных средств пожаротушения - песок, лопаты, багры, огнетушители. \r\nВ целях соблюдения противопожарной безопасности должностные ли￾ца (мастер, прораб) обязаны: \r\n• произвести инструктаж всех участвующих в строительстве лиц с \r\nрегистрацией в специальном журнале; \r\n• знать и точно выполнять противопожарные мероприятия, преду￾смотренные проектом;", "[стр. 59]\n3494.2-ПОС 59 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n• знать и точно выполнять правила пожарной безопасности, осу￾ществлять контроль над соблюдением их всеми работающими на \r\nстроительстве; \r\n• обеспечить наличие, исправное содержание и готовность к при￾менению средств пожаротушения; \r\n• обеспечить отключение после окончания рабочей смены всей \r\nсистемы электроснабжения строительной площадки, кроме де￾журного освещения, освещения мест проходов, проездов терри￾тории строительной площадки; \r\n• регулярно не реже одного раза в смену проверить противопожар￾ное состояние; \r\n• обязательно знать пожарную опасность применяемых в строи￾тельстве материалов и конструкций; \r\n• установить перечень профессий, работники которых должны про￾ходить обучение по программе пожарно-технического минимума; \r\n• установить приказом или распоряжением должностных лиц отве￾чающих за противопожарное производство строительно￾монтажных работ, с организацией добровольных пожарных дру￾жин. \r\nВо всех пожароопасных помещениях должны быть вывешены инструк￾ции, предупредительные надписи и плакаты о мерах пожарной безопасно￾сти, учитывающие особенности этих помещений, средств, мер тушения и \r\nэвакуации людей. Курить на территории строительной площадки разреша￾ется только в специально отведенных местах с надписью: \"Место для куре￾ния\". \r\nОрганизация строительной площадки\r\nВ соответствии с СанПиН 2.2.3.1384-03 «Гигиенические требования к \r\nорганизации строительного производства и строительных работ» до начала \r\nстроительства объекта должны быть выполнены, предусмотренные проек￾том организации строительства (ПОС) и проектом производства работ \r\n(ППР) подготовительные работы по организации стройплощадки. \r\nЭлектрическое освещение строительных площадок и участков подраз￾деляется на рабочее, аварийное, эвакуационное и охранное. \r\nРабочее освещение предусматривается для всех строительных площа￾док и участков, где работы выполняются в ночное и сумеречное время су￾ток, и осуществляется установками общего (равномерного или локализо￾ванного) и комбинированного освещения (к общему добавляется местное).", "[стр. 60]\n3494.2-ПОС 60 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nДля участков работ, где нормируемые уровни освещенности должны \r\nбыть более 2 лк, в дополнение к общему равномерному освещению следует \r\nпредусматривать общее локализованное освещение. Для тех участков, на \r\nкоторых возможно только временное пребывание людей, уровни освещен￾ности могут быть снижены до 0,5 лк. \r\nДля освещения строительных площадок и участков не допускается \r\nприменение открытых газоразрядных ламп и ламп накаливания с прозрач￾ной колбой. \r\nДля освещения мест производства наружных строительных и монтаж￾ных работ применяются такие источники света, как лампы накаливания об￾щего назначения, лампы накаливания прожекторные, лампы накаливания \r\nгалогенные, лампы ртутные газоразрядные высокого давления, лампы ксе￾ноновые, лампы натриевые высокого давления. \r\nОсвещенность, создаваемая осветительными установками общего ос￾вещения на строительных площадках и участках работ внутри зданий, долж￾на быть не менее нормируемой, вне зависимости от применяемых источни￾ков света. \r\nАварийное освещение следует предусматривать в местах производства \r\nработ по бетонированию ответственных конструкций в тех случаях, когда по \r\nтребованиям технологии перерыв в укладке бетона недопустим. \r\nАварийное освещение на участках бетонирования железобетонных кон￾струкций должно обеспечивать освещенность 3 лк, а на участках бетониро￾вания массивов - 1 лк на уровне укладываемой бетонной смеси. \r\nЭвакуационное освещение следует предусматривать в местах основ￾ных путей эвакуации, а также в местах проходов, где существует опасность \r\nтравматизма. Эвакуационное освещение внутри строящегося здания обес￾печивается освещенностью 0,5 лк, вне здания - 0,2 лк. \r\nДля осуществления охранного освещения следует выделять часть све￾тильников рабочего освещения. Охранное освещение должно обеспечивать \r\nна границах строительных площадок или участков производства работ гори￾зонтальную освещенность 0,5 лк на уровне земли или вертикальную на \r\nплоскости ограждения. \r\nТехнологические процессы и оборудование\r\nТехнологические процессы осуществляются в соответствии с гигиени￾ческими требованиями к организации технологических процессов, произ￾водственному оборудованию и рабочему инструменту и СанПиН 2.2.3.1384-\r\n03.", "[стр. 61]\n3494.2-ПОС 61 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПеред началом производства строительных работ работодатель озна￾комляет работников с проектом и проводит инструктаж о принятых методах \r\nработ; установленной последовательности их выполнения; необходимых \r\nсредствах индивидуальной защиты; мероприятиях по предупреждению не￾благоприятного воздействия факторов производственной среды и трудового \r\nпроцесса. \r\nОборудование и материалы, используемые при производстве строи￾тельно-монтажных работ, должны соответствовать гигиеническим, эргоно￾мическим требованиям, а также требованиям настоящих санитарных пра￾вил. \r\nНовое оборудование без наличия положительного санитарно￾эпидемиологического заключения на соответствие требованиям санитарных \r\nправил использоваться при производстве строительно-монтажных работ не \r\nдопускается. \r\nСтроительные машины и механизмы\r\nОборудование, при работе которого возможны выделения вредных га￾зов, паров и пыли, должно поставляться в комплекте со всеми необходимы￾ми укрытиями и устройствами, обеспечивающими надежную герметизацию \r\nисточников выделения вредных веществ. Укрытия должны иметь устройства \r\nдля подключения к аспирационным системам (фланцы, патрубки и т.д.) для \r\nмеханизированного удаления отходов производства. \r\nМашины, при работе которых выделяется пыль (дробильные, размоль￾ные, смесительные и др.), оборудуются средствами пылеподавления или \r\nпылеулавливания. \r\nПри использовании машин, транспортных средств в условиях, установ￾ленных эксплуатационной документацией, уровни шума, вибрации, запы￾ленности, загазованности на рабочем месте машиниста (водителя), а также \r\nв зоне работы машин (механизмов) не должны превышать действующие ги￾гиенические нормативы. \r\nПерсонал, эксплуатирующий средства механизации, оснастку, приспо￾собления и ручные машины, до начала работ обучается безопасным мето￾дам и приемам работ, согласно требованиям инструкций завода￾изготовителя и санитарных правил. \r\nЭксплуатация ручных машин осуществляется при выполнении следую￾щих требований: \r\n• соответствие вибросиловых характеристик действующим гигие￾ническим нормативам;", "[стр. 62]\n3494.2-ПОС 62 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n• проверка комплектности и надежности крепления деталей, ис￾правности защитного кожуха осуществляется при каждой выдаче \r\nмашины в работу; \r\n• ручные машины, масса которых, приходящаяся на руки работаю￾щего, превышает 10 кг, применяются с приспособлениями для \r\nподвешивания; \r\n• проведение своевременного ремонта и послеремонтного контро￾ля параметров вибрационных характеристик. \r\nСтроительные материалы и конструкции\r\nИспользуемые типы строительных материалов (песок, гравий, цемент, \r\nбетон, лакокрасочные материалы и др.) и строительные конструкции долж￾ны иметь санитарно-эпидемиологическое заключение. \r\nНе допускается использование полимерных материалов и изделий с \r\nтоксичными свойствами без положительного санитарно￾эпидемиологического заключения, оформленного в установленном порядке. \r\nЛакокрасочные, изоляционные, отделочные и другие материалы, вы￾деляющие вредные вещества, допускается хранить на рабочих местах в ко￾личествах, не превышающих сменной потребности. \r\nМатериалы, содержащие вредные вещества, хранятся в герметически \r\nзакрытой таре. \r\nПорошкообразные и другие сыпучие материалы следует транспортиро￾вать в плотно закрытой таре. \r\nСтроительные материалы и конструкции должны поступать на строи￾тельные объекты в готовом для использования виде. При их подготовке к \r\nработе в условиях строительной площадки (приготовление смесей и рас￾творов, резка материалов и конструкций и др.) необходимо предусматри￾вать помещения, оснащенные средствами механизации, специальным обо￾рудованием и системами местной вытяжной вентиляции.\r\nОрганизация рабочих мест\r\nРабочие места при выполнении строительных работ должны соответ￾ствовать санитарно-гигиеническим требованиям, а также требованиям Сан￾ПиН 2.2.3.1384-03. \r\nКонцентрации вредных веществ в воздухе рабочей зоны, а также уров￾ни шума и вибрации на рабочих местах не должны превышать установлен￾ных санитарных норм и гигиенических нормативов.", "[стр. 63]\n3494.2-ПОС 63 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПараметры микроклимата должны соответствовать санитарным прави￾лам и нормам по гигиеническим требованиям к микроклимату производст￾венных помещений. \r\nУчастки, на которых проводятся работы с пылевидными материалами \r\nобеспечиваются аспирационными или вентиляционными системами (про￾ветриванием). \r\nМашины и агрегаты, создающие шум при работе, следует эксплуатиро￾вать таким образом, чтобы уровни звука на рабочих местах, на участках и на \r\nтерритории строительной площадки не превышали допустимых величин, \r\nуказанных в санитарных нормах. \r\nПри эксплуатации машин, а также при организации рабочих мест для \r\nустранения вредного воздействия на работающих повышенного уровня шу￾ма следует применять: \r\n• технические средства (уменьшение шума машин в источнике его \r\nобразования; применение технологических процессов, при кото￾рых уровни звука на рабочих местах не превышают допустимые и \r\nт.д.); \r\n• дистанционное управление; \r\n• средства индивидуальной защиты; \r\n• организационные мероприятия (выбор рационального режима \r\nтруда и отдыха, сокращение времени воздействия шумовых фак￾торов в рабочей зоне, лечебно-профилактические и другие меро￾приятия). \r\nЗоны с уровнем звука свыше 80 дБА обозначаются знаками опасности. \r\nРабота в этих зонах без использования средств индивидуальной защиты \r\nслуха не допускается. \r\nНе допускается пребывание работающих в зонах с уровнями звука вы￾ше 135 дБА. \r\nПроизводственное оборудование, генерирующее вибрацию, должно \r\nсоответствовать требованиям санитарных норм. \r\nДля устранения вредного воздействия вибрации на работающих следу￾ет предусматривать следующие мероприятия: \r\n• снижение вибрации в источнике ее образования конструктивными \r\nили технологическими мерами; \r\n• уменьшение вибрации на пути ее распространения средствами \r\nвиброизоляции и вибропоглощения;", "[стр. 64]\n3494.2-ПОС 64 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n• дистанционное управление, исключающее передачу вибрации на \r\nрабочие места; \r\n• средства индивидуальной защиты; \r\n• организационные мероприятия (рациональные режимы труда и \r\nотдыха, лечебно-профилактические и другие мероприятия). \r\nРабочие места, где применяются или приготовляются клеи, мастики, \r\nкраски и другие материалы, выделяющие вредные вещества, обеспечива￾ются проветриванием, а закрытые помещения оборудуются механической \r\nсистемой вентиляции. \r\nОсвещение рабочих мест должно соответствовать установленным тре￾бованиям санитарных правил. \r\nПри выполнении строительно-монтажных работ, помимо контроля за \r\nвредными производственными факторами, обусловленными строительным \r\nпроизводством, организуется производственный контроль за соблюдением \r\nсанитарных правил в установленном порядке. \r\nОрганизация и производство строительных работ\r\nПри выполнении отделочных или антикоррозийных работ в закрытых \r\nпомещениях с применением вредных химических веществ предусматрива￾ется оборудование естественной и механической вентиляции, а также ис￾пользование работниками средств индивидуальной защиты. \r\nПри выполнении строительных работ в условиях действия опасных или \r\nвредных производственных факторов санитарно-бытовые и производствен￾ные помещения размещаются за пределами опасных зон.\r\nПроизводство работ на строительном объекте следует вести в техноло￾гической последовательности, при необходимости совмещения работ про￾водятся дополнительные мероприятия по обеспечению условий труда, от￾вечающих требованиям настоящих санитарных правил. \r\nОрганизация работ на открытой территории в холодный период года\r\nРаботы в холодное время года проводятся при соблюдении требований \r\nк мерам защиты работников от охлаждения. \r\nРаботающие на открытой территории в холодный период года обеспе￾чиваются комплектом средств индивидуальной защиты (СИЗ) от холода с \r\nучетом климатического региона (пояса). При этом комплект СИЗ должен \r\nиметь положительное санитарно-эпидемиологическое заключение с указа￾нием величины его теплоизоляции. \r\nВо избежание локального охлаждения работающих следует обеспечи￾вать рукавицами, обувью, головными уборами. На рукавицы, обувь, голов-", "[стр. 65]\n3494.2-ПОС 65 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nные уборы должны быть положительные санитарно-эпидемиологические \r\nзаключения с указанием величин их теплоизоляции. \r\nПри разработке внутрисменного режима работы следует ориентиро￾ваться на допустимую степень охлаждения работающих, регламентируемую \r\nвременем непрерывного пребывания на холоде и временем обогрева. \r\nТемпература воздуха в местах обогрева поддерживается на уровне 21 - \r\n25 °С. Помещение следует также оборудовать устройствами, температура \r\nкоторых не должна быть выше 40 °С (35 - 40 °С), для обогрева кистей и \r\nстоп. \r\nПродолжительность первого периода отдыха допускается ограничить \r\n10 минутами, продолжительность каждого последующего следует увеличи￾вать на 5 минут. \r\nВ помещении для обогрева следует снимать верхнюю утепленную оде￾жду. \r\n Во избежание переохлаждения работникам не следует во время пе￾рерывов в работе находиться на холоде (на открытой территории) в течение \r\nболее 10 минут при температуре воздуха до -10 °С и не более 5 минут при \r\nтемпературе воздуха ниже -10 °С. \r\nПерерывы на обогрев могут сочетаться с перерывами на восстановле￾ние функционального состояния работника после выполнения физической \r\nработы. В обеденный перерыв работник обеспечивается «горячим» питани￾ем. Начинать работу на холоде следует не ранее, чем через 10 минут после \r\nприема «горячей» пищи (чая и др.). \r\nПри температуре воздуха ниже -30 °С не рекомендуется планировать \r\nвыполнение физической работы категории выше IIа. При температуре воз￾духа ниже -40 °С следует предусматривать защиту лица и верхних дыха￾тельных путей. \r\nОрганизация труда и отдыха\r\nРежимы труда и отдыха работников, осуществляющих строительные \r\nработы должны соответствовать требованиям действующих нормативных \r\nправовых актов и СанПиН 2.2.3.1384-03. \r\nРациональные режимы труда и отдыха работников разрабатываются \r\nна основании результатов конкретных физиолого-гигиенических исследова￾ний с учетом неблагоприятного воздействия комплекса факторов производ￾ственной среды и трудового процесса. \r\nПри организации режима труда регламентируются перерывы для прие￾ма пищи.", "[стр. 66]\n3494.2-ПОС 66 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПри организации режимов труда и отдыха работающих в условиях на￾гревающего или охлаждающего микроклимата следует включать в соответ￾ствии с настоящими санитарными правилами требования к продолжитель￾ности непрерывного пребывания в охлаждающем и нагревающем микро￾климате, перерывы в целях нормализации теплового состояния человека, \r\nкоторые могут быть совмещены с отдыхом после выполнения физической \r\nработы. \r\nПри использовании ручных инструментов, генерирующих вибрацию, \r\nработы следует проводить в соответствии с гигиеническими требованиями к \r\nручным инструментам и организации работ. \r\nРежимы труда работников, подвергающихся воздействию шума, следу￾ет разрабатывать в соответствии с гигиеническими критериями оценки и \r\nклассификации условий труда по показателям вредности и опасности фак￾торов производственной среды, тяжести и напряженности трудового про￾цесса. \r\nГигиенические требования к обеспечению спецодеждой, спецобувью, \r\nголовными уборами и средствами индивидуальной защиты \r\nРаботникам, занятым на работах с вредными или опасными условиями \r\nтруда, а также на работах, выполняемых в особых температурных условиях \r\nили связанных с загрязнением, выдаются бесплатно за счет работодателя \r\nспециальная одежда, специальная обувь и другие средства индивидуальной \r\nзащиты (СИЗ) в соответствии с нормами, утвержденными в установленном \r\nпорядке. \r\nГигиенические требования к средствам индивидуальной защиты долж￾ны соответствовать требованиям санитарных правил и иметь санитарно￾эпидемиологическое заключение, оформленное в установленном порядке. \r\nВыдаваемые работникам средства индивидуальной защиты должны \r\nсоответствовать их полу, росту и размерам, характеру и условиям выпол￾няемой работы и обеспечивать в течение заданного времени снижение воз￾действия вредных и опасных факторов производства на организм человека \r\nдо допустимых величин, определяемых нормативными документами. \r\nРаботники к работе в неисправной, не отремонтированной, загрязнен￾ной специальной одежде и специальной обуви, а также с неисправными \r\nСИЗ не допускаются. \r\nРаботники своевременно ставят в известность работодателя о необхо￾димости химчистки, стирки, сушки, ремонта, дегазации, дезактивации, де-", "[стр. 67]\n3494.2-ПОС 67 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nзинфекции, обезвреживания и обеспыливания специальной одежды, специ￾альной обуви и других средств индивидуальной защиты. \r\nРаботодатель при выдаче работникам таких СИЗ, как респираторы, \r\nпротивогазы, самоспасатели, предохранительные пояса, накомарники, каски \r\nи другие, обеспечивает проведение инструктажа работников по правилам \r\nпользования и простейшим способам проверки исправности этих средств, а \r\nтакже тренировку по их применению. \r\nРаботодатель обеспечивает регулярные испытание и проверку исправ￾ности средств индивидуальной защиты, а также своевременную замену час￾тей СИЗ с понизившимися защитными свойствами. \r\nДля хранения выданных работникам СИЗ работодатель оборудует спе￾циальные помещения (гардеробные). \r\nРаботодатель организует надлежащий уход за средствами индивиду￾альной защиты и их хранение, своевременно осуществляет химчистку, стир￾ку, ремонт, дегазацию, дезактивацию, обезвреживание и обеспыливание \r\nспециальной одежды, специальной обуви и других средств индивидуальной \r\nзащиты. В тех случаях, когда это требуется по условиям производства, в ор￾ганизации (в цехах, на участках) устраиваются сушилки для специальной \r\nодежды и обуви, камеры для обеспыливания специальной одежды и уста￾новки для дегазации, дезактивации и обезвреживания средств индивиду￾альной защиты. \r\nРаботодатель обеспечивает выдачу смывающих и обезвреживающих \r\nсредств в соответствии с установленными нормами работникам, занятым на \r\nработах, связанных с загрязнением тела. \r\nПри умывальниках должно быть мыло и регулярно сменяемые поло￾тенца или воздушные осушители рук. \r\nПри работах с веществами, вызывающими раздражение кожи рук, \r\nдолжны выдаваться профилактические пасты и мази, а также смывающие и \r\nдезинфицирующие средства. \r\nСанитарно-бытовые помещения\r\nУстройство и оборудование санитарно-бытовых зданий и помещений, \r\nпредусмотренных в проектах организации строительства и производства \r\nработ вновь строящихся и реконструируемых объектов, должно быть за￾вершено до начала строительных работ. \r\nВ состав санитарно-бытовых помещений входят гардеробные, душе￾вые, умывальни, санузлы, курительные, места для размещения полудушей, \r\nустройств питьевого водоснабжения, помещения для обогрева или охлаж-", "[стр. 68]\n3494.2-ПОС 68 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nдения, обработки, хранения и выдачи спецодежды. В соответствии с ведом￾ственными нормативными документами допускается предусматривать в до￾полнение к указанным и другие санитарно-бытовые помещения и оборудо￾вание. \r\nПеред входом в санитарно-бытовые помещения непосредственно с \r\nулицы предусматривается тамбур, у входа в который следует устраивать \r\nприспособления для очистки и мытья обуви. \r\nПередвижные санитарно-бытовые помещения оборудуются мебелью и \r\nнеобходимым инвентарем, которые прочно прикрепляются к полу и стенам. \r\nСанитарно-бытовые помещения оборудуются внутренним водопрово￾дом, канализацией и отоплением. \r\nПитьевое водоснабжение\r\nВсе строительные рабочие обеспечиваются доброкачественной питье￾вой водой, отвечающей требованиям действующих санитарных правил и \r\nнормативов. \r\nСреднее количество питьевой воды, потребное для одного рабочего, \r\nопределяется 1,0 - 1,5 л зимой; 3,0 - 3,5 л летом. Температура воды для \r\nпитьевых целей должна быть не ниже 8 °С и не выше 20 °С. \r\nВнутренняя планировка санитарно-бытовых помещений должна исклю￾чать смешивание потоков рабочих в чистой и загрязненной одежде. \r\nУстройство помещений для сушки специальной одежды и обуви, их \r\nпропускная способность и применяемые способы сушки должны обеспечи￾вать полное просушивание спецодежды и обуви к началу рабочей смены. \r\nЗдравпункты для обслуживания строительных рабочих располагают \r\nлибо в отдельном помещении сборно-разборного или передвижного типа, \r\nлибо в составе бытовых помещений с отдельным входом и удобным подъ￾ездом санитарных машин. Состав и размеры помещений здравпунктов \r\nдолжны соответствовать требованиям действующей нормативной докумен￾тации. \r\nНа всех участках и в бытовых помещениях оборудуются аптечки первой \r\nпомощи. Обеспечивается систематический контроль и при снабжение (при \r\nнеобходимости) лекарственными средствами и средствами индивидуальной \r\nзащиты. \r\nПогрузо-разгрузочные работы\r\nПри выполнении погрузо-разгрузочных работ вручную следует соблю￾дать требования законодательства о предельных нормах переносимых гру￾зов и допуске работников к выполнению этих работ.", "[стр. 69]\n3494.2-ПОС 69 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПогрузо-разгрузочные работы следует выполнять механизированным \r\nспособом с использованием подъемно-транспортного оборудования. \r\nМеханизированный способ погрузо-разгрузочных работ является обя￾зательным для грузов весом более 50 кг, а также при подъеме грузов на вы￾соту более 2м. \r\nПереносить материалы на носилках по горизонтальному пути допуска￾ется только в исключительных случаях и на расстояние не более 50м. \r\nСклады, расположенные выше первого этажа и имеющие лестницы с \r\nколичеством маршей более одного или высоту более 2м, оборудуются \r\nподъемником для спуска и подъема грузов. \r\nНе допускается выполнять погрузо-разгрузочные работы с опасными \r\nгрузами при обнаружении несоответствия тары требованиям нормативно￾технической документации, утвержденной в установленном порядке, неис￾правности тары, а также при отсутствии маркировки и предупредительных \r\nнадписей на ней. \r\nПогрузо-разгрузочные операции с сыпучими, пылевидными и опасными \r\nматериалами производятся с применением средств механизации и исполь￾зованием средств индивидуальной защиты, соответствующих характеру вы￾полняемых работ. \r\nДопускается выполнять вручную погрузо-разгрузочные операции с пы￾левидными материалами (цемент, известь и др.) при температуре материа￾ла не более 40 °С. \r\n19.1 ТЕХНИКА БЕЗОПАСНОСТИ И ПРОТИВОПОЖАРНЫЕ\r\nМЕРОПРИЯТИЯ В ПЕРИОД ОРГАНИЗАЦИИ СТРОИТЕЛЬСТВА\r\nПроизводство строительно-монтажных работ должно осуществляться в \r\nсоответствии с требованиями СНиП 12-04-2002 «Безопасность труда в \r\nстроительстве», СНиП 12-01-2004 «Организация строительства», ППБ 01-03 \r\nМВД СССР «Правила пожарной безопасности в РФ», ПБ 10-382-00 «Прави￾ла устройства и безопасной эксплуатации грузоподъемных кранов». Учиты￾вая условия работ, предусматриваются следующие обязательные требова￾ния по технике безопасности: \r\n― предусмотреть устройство водоотлива и водоотвода (весенний па￾водок); \r\n― монтаж конструкций производить непосредственно с транспортных \r\nсредств и площадок складирования;", "[стр. 70]\n3494.2-ПОС 70 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n― опасные зоны производства работ оградить и установить знаки \r\nбезопасности в соответствии с требованиями ГОСТ 12.4.059-89, \r\nСНиП 12-03-2001, ч.1 и СНиП 12-04-2002, ч.2; \r\n― границу опасной зоны действия крана оградить сигнальными ограж￾дениями (в соответствии со СНиП 12-03-2001); \r\n― для предотвращения раскачивания монтируемых элементов ис￾пользовать багры и оттяжки. \r\nУстройство на стройплощадке электросетей производится в строгом \r\nсоответствии с Правилами устройства электроустановок (ПУЭ). \r\nОсобое внимание следует уделить следующим вопросам безопасности: \r\n― ограждению проемов и проходов; \r\n― надежному заземлению механизмов; \r\n― соблюдению правил складирования материалов и конструкций; \r\n― достаточному освещению строительной площадки; \r\n― своевременной уборке строительного мусора с проездов и прохо￾дов, площадок; \r\n― на захватке, где ведутся СМР, не допускается выполнение других \r\nвидов работ, а также нахождение посторонних лиц; \r\n― крюки кранов и подъемных приспособлений должны оборудоваться \r\nустройствами, предохраняющими от самопроизвольной расстропов￾ки; \r\n― перед началом укладки бетона проверяется состояние опалубки, \r\nсредств подмащивания; \r\n― перед укладкой бетона из бадей расстояние между нижней кромкой \r\nбадьи и поверхностью, на которую принимается бетон, должно быть \r\nне более 1,0 м; \r\n― бетонирование железобетонных конструкций допускается после \r\nконтрольной приемки арматуры, закладных частей и отверстий \r\nпредставителями монтажных организаций по специальностям. \r\nВсе рабочие должны иметь допуск к работе на высоте и пройти меди￾цинский осмотр, а также пройти инструктаж на рабочем месте. Должны быть \r\nобеспечены средствами защиты, соответствующими характеру выполняе￾мой работы. Работы должны вестись под непосредственным руководством \r\nмастера или прораба. При производстве работ необходимо также соблю￾дать правила пожарной безопасности РФ. Вдоль проектируемых объектов \r\nпредусматривается устройство проезда, обеспечивающего проезд пожар￾ных машин.", "[стр. 71]\n3494.2-ПОС 71 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n20. ОПИСАНИЕ ПРОЕКТНЫХ РЕШЕНИЙ И МЕРОПРИЯТИЙ ПО \r\nОХРАНЕ ОКРУЖАЮЩЕЙ СРЕДЫ В ПЕРИОД СТРОИТЕЛЬСТВА \r\nПри организации строительного производства необходимо соблюдать \r\nтребования СНиП 1.02.01-85, СНиП 3.01.01.-85, ГОСТ 17.1.1.01-77, ГОСТ \r\n17.2.1.04-77 по охране окружающей среды, ФЗ РФ «Об охране окружающей \r\nприродной среды» и раздела 9 «Охрана природы» СНиП 3.02.01-87. \r\nСтоянку и заправку строительных механизмов ГСМ следует произво￾дить на специализированных площадках, не допуская их пролив и попада￾ние на грунт. После заправки пролитое масло и топливо должны быть не￾медленно вытерты. \r\nНа машинах должен находиться исправный огнетушитель, а в местах \r\nстоянки машин должны стоять ящики с песком. Не допускается стоянка ма￾шин и механизмов с работающими двигателями. \r\nС целью исключения рассыпания грунта с кузовов автосамосвалов, \r\nрассеивания его во время движения кузова нагруженных грунтом автосамо￾свалов накрывать полотнищами брезента. Брезент должен надежно закреп￾ляться к бортам. \r\nВ целях наименьшего загрязнения окружающей среды предусматрива￾ется центральная поставка растворов и бетонов специализированным \r\nтранспортом. \r\nПри производстве работ принимать конструктивные и технологические \r\nмеры по снижению уровня шума. Для уменьшения количества пыли времен￾ные дороги, особенно в сухой жаркий период периодически поливать водой. \r\nПри выезде со строительной площадки предусматривается место \r\n(пункт) для мойки колес автотранспорта. \r\nВ период строительства предусматриваются следующие мероприятия \r\nпо охране почв: \r\n• устройство поверхностного водоотвода со строительной площад￾ки в благоустроенные придорожные канавы; \r\n• срезка растительного слоя почв и временное хранение его в бур￾тах; \r\n• восстановление поврежденных участков почвы на участке строи￾тельства. \r\nУдаление бытовых и строительных отходов выполнять в соответствии с \r\nтребованиями СНиП 2.07.01-89*, собирая их в закрывающиеся стальные \r\nконтейнеры, исключающие загрязнение окружающей среды. По мере накоп-", "[стр. 72]\n3494.2-ПОС 72 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nления мусор вывозят силами специализированной лицензированной орга￾низации на полигоны для хранения и утилизации. \r\nДеревья, находящиеся на территории строительной площадки, переса￾живают или сносят по согласованию с природоохранными органами. После \r\nокончания строительных работ осуществляется посадка зеленых насажде￾ний. \r\nПри производстве работ не разрешается превышение предельно до￾пустимых концентраций вредных веществ в воздухе рабочей зоны, при этом \r\nнеобходимо пользоваться приборами, применяемыми для санитарно￾гигиенической оценки вредных производственных факторов. \r\nК числу мероприятий по охране окружающей среды относятся восста￾новление нарушенных территорий, вертикальная планировка образованных \r\nповерхностей, максимальное сохранение зеленых насаждений, проведение \r\nработ по озеленению. \r\nГигиенические требования к охране окружающей среды\r\nПри проведении строительных работ следует предусматривать макси￾мальное применение малоотходной и безотходной технологии с целью ох￾раны атмосферного воздуха, земель, лесов, вод и других объектов окру￾жающей природной среды. \r\nСбор и удаление отходов, содержащих токсические вещества, следует \r\nосуществлять в закрытые контейнеры или плотные мешки, исключая ручную \r\nпогрузку. Сточные воды следует собирать в накопительные емкости с ис￾ключением фильтрации в подземные горизонты. \r\nНе допускается сжигание на строительной площадке строительных от￾ходов. \r\nЕмкости для хранения и места складирования, разлива, раздачи горю￾че-смазочных материалов и битума оборудуются специальными приспособ￾лениями и выполняются мероприятия для защиты почвы от загрязнения. \r\nБытовой мусор и нечистоты следует регулярно удалять с территории \r\nстроительной площадки в установленном порядке и в соответствии с требо￾ваниями действующих санитарных норм. \r\nПоступающее сырье, виды и количество отходов, класс опасности от￾ходов, образующихся в процессе строительства обогатительной фабрики \r\nи объектов хвостового хозяйства представлены в разделе 8 «Перечень ме￾роприятий по охране окружающей среды» ( 3477−ООС, том 5.7). \r\nЗемлю и земельные угодья, нарушенные при строительстве, следует \r\nрекультивировать к началу сдачи объекта в эксплуатацию", "[стр. 73]\n3494.2-ПОС 73 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПри производстве строительно-монтажных работ необходимо преду￾смотреть следующие мероприятия, обеспечивающие уменьшение загрязне￾ния атмосферы, воды, почвы в процессе строительства: \r\n• своевременное и качественное устройство подъездных внеплощадоч￾ных и внутриплощадочных (временных) дорог; \r\n• устройство закрытого хранения, погрузки и перевозки сыпучих пыля￾щих материалов (применение контейнеров, специальных транспорт￾ных средств); \r\n• применение герметических емкостей для перевозки бетона и раствора; \r\n• производство работ на действующем предприятии осуществлять по \r\nакту-допуску, оформленному согласно СНиП 12-03-2001, подписанно￾му генподрядчиком и предусматривающему мероприятия, обеспечи￾вающие безопасное выполнение работ; \r\n• место производства работ должно быть ограждено сигнальными и за￾щитными ограждениями согласно требованиям СНиП 12-03-2001; \r\n• при уборке отходов и мусора не допускается сбрасывать их в пони￾женные места рельефа; \r\n• строительный мусор вывозятся на свалку; \r\n• утилизация твердых бытовых отходов и вывоз мусора предусмотрены \r\nна соответствующие полигоны; \r\n• производственные и бытовые стоки, образующиеся на строительной \r\nплощадке, должны направляться на очистку и обезвреживание на очи￾стные сооружения; \r\n• при эксплуатации грузоподъемных механизмов и автомобилей исклю￾чается слив масел и сточных вод на рельеф. \r\n• соблюдение требования местных органов охраны природы. \r\n Для минимизации негативных последствий освоения территории и \r\nобеспечения безопасности населения предусмотрено: \r\n• зонирование территории с максимальным учетом природно￾хозяйственной ценности конкретных участков; \r\n• соблюдение санитарных разрывов между селитебной и промышлен￾ной зонами; \r\n• организация водоохранных зон на основе разработки проектов водо￾охранных и санитарно-защитных зон; \r\n• использование прогрессивных технических и технологических реше￾ний, обеспечивающих безопасность населения и допустимые нагрузки \r\nна природную среду.", "[стр. 74]\n3494.2-ПОС 74 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n21. ОБОСНОВАНИЕ ПРИНЯТОЙ ПРОДОЛЖИТЕЛЬНОСТИ \r\nСТРОИТЕЛЬСТВА ОБЪЕКТА КАПИТАЛЬНОГО СТРОИТЕЛЬСТВА И \r\nЕГО ОТДЕЛЬНЫХ ЭТАПОВ \r\nПредлагается строительство нового хвостохранилища ТОФ выполнить \r\nв две очереди. \r\nПервая очередь строительства предусматривает организацию хвосто￾хранилища площадью 7,1 км2\r\n на территории недействующего отстойника \r\nХараелах и недействующего карьера \"Дальний\". \r\nВторая очередь строительства предусматривает расширение хвостохра￾нилища путём прирезки территории с северной стороны площадью 3,85 км2\r\n. \r\nОбщая площадь хвостохранилища составит 10,95 км2\r\n. \r\nВыделение первой очереди строительства обусловлено необходимо￾стью поддержания баланса воды в отстойном пруде хвостохранилища за \r\nсчёт уменьшения водопритока с площади хвостохранилища, что обеспечит \r\nего эксплуатацию в бессточном режиме в период работы второго пускового \r\nкомплекса ТОФ. \r\nОсновной объем строительно-монтажных работ выполняет генподряд￾чик своими силами. На специальные монтажные работы привлекаются спе￾циализированные субподрядные организации. \r\n Продолжительность строительства определяется в соответствии со \r\nСНиП 1.04.03-85 часть 2 раздел 4 п.21. с применением коэффициента 1,35. \r\nОтсыпка дамб обвалования производится только при положительных тем￾пературах. Продолжительность и последовательность строительства про￾ектируемых сооружений представлена в календарном плане на чертеже \r\n3494-ПОС лист 1. \r\n22. СТРОЙГЕНПЛАН И ТРАНСПОРТ \r\nСтройгенпланы разработан на период возведения зданий хвостового \r\nхозяйства. \r\nНа стройгенплане обозначены: \r\n— временные автодороги по проектируемым автодорогам; \r\n— бытовой городок (временные инвентарные здания); \r\n— площадки для временной стоянки автотранспорта и складирования \r\nконструкций и изделий.", "[стр. 75]\n3494.2-ПОС 75 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПодвоз стройматериалов и конструкций в зону строительства со строй￾базы Генподрядчика производится автотранспортом по существующим и \r\nвновь проектируемым автодорогам. \r\nРасположение временных дорог принять по проектируемым постоян￾ным дорогам. \r\nВременную дорогу организовать с двусторонним движением авто￾транспорта. Покрытие временных дорог выполнить из щебня. \r\nВременные здания обеспечиваются электроэнергией, питьевой водой и \r\nисточниками обогрева. \r\nДля хранения арматуры, металлических конструкций и закладных дета￾лей предусмотреть устройство навесов. Штабели для складирования конст￾рукций организовать в соответствии со СНиП 12-01-2004, СНиП 12-03-2001 \r\nи СНиП 12-04-2002, соблюдая установленные высоты штабелей и ширину \r\nпроходов между ними. \r\nШтабели металлоконструкций и арматуры должны дополнительно укры￾ваться полиэтиленовой пленкой или иным гидроизоляционным материалом. \r\nПри производстве СМР (бетонирование и др.) предусмотреть дополни￾тельное освещение рабочих мест со степенью освещенности не менее 25 \r\nлк. \r\nПрожекторы и светильники установить на отдельно стоящих столбах \r\nили стойках. Кабель питания светильников расположить на высоте не менее \r\n2.0 м. Крепление прожекторов к стволам растущих деревьев запрещается. \r\nПрокладку силового кабеля на строительной площадке до временных зда￾ний (до распределительного щита марки ЩС) выполнить в воздушном вариан￾те на опорах. Высота подвески силового кабеля должна быть не менее 2.0 м. \r\nПереходы кабеля через временные дороги выполнить над землей. \r\n23.ТЕХНИКО-ЭКОНОМИЧЕСКИЕ ПОКАЗАТЕЛИ \r\nТехнико-экономические показатели хвостовому хозяйству приведены в \r\nтаблице 12.", "[стр. 76]\n3494.2-ПОС 76 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nТаблица 12 \r\nТехнико-экономические показатели\r\n№\r\nп /п Наименование Ед. изм. Количество \r\n1 Сметная стоимость СМР первой очереди \r\nстроительства \r\nтыс.руб. 14 823 309,1 \r\nСметная стоимость СМР второй очереди \r\nстроительства \r\nтыс.руб. 1 326 314,87 \r\n2 Продолжительность строительства: \r\n-полный срок строительства мес. 75 \r\n3 Количество работающих \r\n(на максимально-напряженный год) чел. 364 \r\n4 Выработка на одного основного рабочего \r\nв год \r\nмлн.руб 19850 \r\n24. ПЕРЕЧЕНЬ МЕРОПРИЯТИЙ ПО ОРГАНИЗАЦИИ МОНИТОРИНГА\r\nЗА СОСТОЯНИЕМ ЗДАНИЙ И СООРУЖЕНИЙ, РАСПОЛОЖЕННЫХ В \r\nНЕПОСРЕДСТВЕННОЙ БЛИЗОСТИ ОТ СТРОЯЩЕГОСЯ ОБЪЕКТА, \r\nЗЕМЛЯНЫЕ, СТРОИТЕЛЬНЫЕ, МОНТАЖНЫЕ И ИНЫЕ РАБОТЫ НА \r\nКОТОРЫЕ МОГУТ ПОВЛИЯТЬ НА ТЕХНИЧЕСКОЕ СОСТОЯНИЕ И \r\nНАДЕЖНОСТЬ ТАКИХ ЗДАНИЙ И СООРУЖЕНИЙ \r\nСтроительство ведется на свободной от застройки территории, меро￾приятия по организации мониторинга за состоянием зданий и сооружений \r\nне требуется.", "[стр. 77]\n3494.2-ПОС 77 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПРИЛОЖЕНИЯ", "[стр. 78]\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\n3494.2-ПОС 78 \r\nПРИЛОЖЕНИЕ А \r\nВЕДОМОСТЬ ПОТРЕБНОСТИ В СТРОИТЕЛЬНЫХ МАТЕРИАЛАХ, КОНСТРУКЦИЯХ\r\n№ \r\nп/п Наименование Ед. изм. Объем работ, \r\nвсего \r\nНасосная станция \r\nоборотной воды (3)\r\nПлавучая \r\nнасосная станция \r\nоборотной воды (4)\r\nУзел переключе￾ния водоводов и \r\nпульповодов (6) \r\nУзел переключе￾ния трубопрово￾дов №1 (8) Пульпонасосная станция №1А (13) \r\n1 Строительный объем 15489,1 7000 13,1 3500 3500 1476 \r\n2 Щебень м3 500 250 - 125 125 - \r\n3 ПГС м3 2100 900 - 600 600 - \r\n4 Бетон товарный м3 1941 1235 - 314 314 48 \r\n5 Цемент т 1,7 0,5 - 0,5 0,5 0,2 \r\n6 Металлоконструкции т 196,2 90 6,2 35 35 30 \r\n7 Электроды сварочные т 1,19 0,54 0,05 0,21 0,21 0,18 \r\n8 Арматурная сталь т 143,84 89,84 - 25 25 4 \r\n9 Профнастил т 16,5 8 0,5 4 4 - \r\n10 3-х слойные панели м2/т 2200/77 1100/38,5 - 550/19,25 550/19,25 - \r\n11 Сталь листовая т 0,8 0,5 0,1 0,1 0,1 - \r\n12 Сталь оцинкованная м2 2,3 2 0,1 0,1 0,1 - \r\n13 Крановые рельсы т 11 4 0.8 3,1 3,1 - \r\n14 Лес круглый м3 6 2 - 2 2 - \r\n15 Пиломатериалы обрез￾ные м3 32 10 - 10 10 2 \r\n16 Метизы (поковки, за- кладные детали т.д.) т 2,6 1 - 0,8 0,8 - \r\n17 Кирпич м3 82 - - - - 82 \r\n18 Рулонные кровельные \r\nматериалы м2 1510 615 7 360 360 168 \r\n19 Оконные заполнения м2 82,54 37 0,54 18 18 9 \r\n20 Дверные заполнители м2 83,9 47 1,9 11 11 13 \r\n21 Металлические двери и \r\nворота м2/т 80/16 36/7,2 - 22/4,4 22/4,4 - \r\n22 Трубы стальные т 2,03 2,03 - \r\n23 Битум т 1,3 0,5 - 0,35 0,35 0,1 \r\n24 Теплоизоляция м3/т 603/3,1 200/1 3/0,1 200/1 200/1 -", "[стр. 79]\n3494.2-ПОС 79 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nЧЕРТЕЖИ", "[стр. 80]\n3494.2-ПОС 80 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nПЕРЕЧЕНЬ ЧЕРТЕЖЕЙ \r\n№№ \r\nп.п.\r\nНаименование чертежей Шифр и номер \r\nчертежа\r\n1 Календарный план строительства 1 и 2 очереди \r\nстроительства \r\n3494-ПОС \r\nлист 1 \r\n2 Стройгенплан. Насосная станция оборотной воды 3494-3-ПОС \r\nлист 1 \r\n3 Стройгенплан. Узел переключения трубопроводов N1 3494-8-ПОС \r\nлист 1 \r\n4 Стройгенплан. Узел переключения трубопроводов N2 3494-6-ПОС \r\nлист 1", "[стр. 81]\n3494.2-ПОС 85 \r\nD:\\2011\\ТАЛНАХ\\3494-2-ПОС-изм3.doc \r\nТАБЛИЦА РЕГИСТРАЦИИ ИЗМЕНЕНИЙ\r\nНомера листов \r\n(по сквозной нумерации тома) \r\nИзм.\r\nизме￾нённых \r\nзаме￾нён￾ных \r\nновых \r\nаннули￾рован￾ных \r\nВсего \r\nлистов \r\nв док. \r\nНомер \r\nдок. \r\nПодп. Дата \r\n3 \r\n41, 42, 43, \r\n45, 47, 48, \r\n49, 76, 80 \r\n81 1-2013"]};
